package xyz.peppie.splashhelper;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SplashHelperPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SplashHelperPlugin.class);
		RuneLite.main(args);
	}
}

package xyz.peppie.splashhelper;

import xyz.peppie.splashhelper.model.TargetNpc;
import xyz.peppie.splashhelper.model.SplashSpell;
import xyz.peppie.splashhelper.model.OverallStatField;
import xyz.peppie.splashhelper.model.SessionStatField;
import java.awt.Color;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.ModifierlessKeybind;
import net.runelite.client.config.Range;

@ConfigGroup("splashhelper")
public interface SplashHelperConfig extends Config
{
	@ConfigItem(
		keyName = "enableWelcomeMessage",
		name = "Enable Welcome Message",
		description = "Display a welcome message when logging in"
	)
	default boolean enableWelcomeMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "targetNpc",
		name = "Target NPC",
		description = "Select the NPC to track for splashing"
	)
	default TargetNpc targetNpc()
	{
		return TargetNpc.KNIGHT_OF_ARDOUGNE;
	}

	@ConfigItem(
		keyName = "timerDuration",
		name = "Timer Duration (minutes)",
		description = "How many minutes the timer should count down"
	)
	default int timerDuration()
	{
		return 15;
	}

	@Range(min = 1, max = 120)
	@ConfigItem(
		keyName = "timerWarningMinutes",
		name = "Warning Threshold (minutes)",
		description = "Timer text and screen tint turn orange when this many minutes remain. Clamped to the timer duration."
	)
	default int timerWarningMinutes()
	{
		return 5;
	}

	@Range(min = 1, max = 120)
	@ConfigItem(
		keyName = "timerCriticalMinutes",
		name = "Critical Threshold (minutes)",
		description = "Timer text and screen tint turn red when this many minutes remain. Clamped to the warning threshold."
	)
	default int timerCriticalMinutes()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show Timer Overlay",
		description = "Display the timer overlay on screen"
	)
	default boolean showOverlay()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "boundaryTileColor",
		name = "Boundary Tile Color",
		description = "Color of the boundary tile marker"
	)
	default Color boundaryTileColor()
	{
		return new Color(255, 0, 0, 100); // Semi-transparent red
	}

	@Alpha
	@ConfigItem(
		keyName = "knightTile1Color",
		name = "Knight Tile 1 Color",
		description = "Color of the Knight Tile 1 marker"
	)
	default Color knightTile1Color()
	{
		return new Color(0, 255, 0, 255); // Green
	}

	@Alpha
	@ConfigItem(
		keyName = "knightTile2Color",
		name = "Knight Tile 2 Color",
		description = "Color of the Knight Tile 2 marker"
	)
	default Color knightTile2Color()
	{
		return new Color(0, 0, 255, 255); // Blue
	}

	// ==================== Notification Settings ====================

	@ConfigSection(
		name = "Notifications",
		description = "Configure notification behavior",
		position = 10
	)
	String notificationSection = "notifications";

	@ConfigItem(
		keyName = "enableBoundaryNotification",
		name = "Boundary Notification",
		description = "Notify when knight reaches boundary tile",
		section = notificationSection
	)
	default boolean enableBoundaryNotification()
	{
		return true;
	}

	@ConfigItem(
		keyName = "enableTimerNotification",
		name = "Timer Notification",
		description = "Notify when splash timer expires",
		section = notificationSection
	)
	default boolean enableTimerNotification()
	{
		return true;
	}

	@ConfigItem(
		keyName = "enableHpNotification",
		name = "HP Threshold Notification",
		description = "Notify when HP drops below threshold (only when knight can attack)",
		section = notificationSection
	)
	default boolean enableHpNotification()
	{
		return true;
	}

	@Range(min = 1, max = 99)
	@ConfigItem(
		keyName = "hpThreshold",
		name = "HP Threshold",
		description = "HP level at which to notify (when knight can attack)",
		section = notificationSection
	)
	default int hpThreshold()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "enableSoundNotification",
		name = "Sound Notification",
		description = "Play a notification sound (Windows toast + native sound)",
		section = notificationSection
	)
	default boolean enableSoundNotification()
	{
		return true;
	}

	@ConfigItem(
		keyName = "useVisualNotification",
		name = "Visual Notification",
		description = "Show a screen tint when the timer reaches the warning (orange) and critical (red) thresholds, and on notifications",
		section = notificationSection
	)
	default boolean enableVisualNotification()
	{
		return false;
	}

	@Range(min = 1, max = 30)
	@ConfigItem(
		keyName = "notificationDuration",
		name = "Notification Duration",
		description = "How long notifications are displayed (in seconds)",
		section = notificationSection
	)
	default int notificationDuration()
	{
		return 5;
	}

	// ==================== Statistics Settings ====================

	@ConfigSection(
		name = "Statistics",
		description = "Configure statistics tracking",
		position = 20
	)
	String statisticsSection = "statistics";

	@ConfigItem(
		keyName = "enableStatistics",
		name = "Enable Statistics",
		description = "Track splashing session statistics",
		section = statisticsSection
	)
	default boolean enableStatistics()
	{
		return true;
	}

	@Range(min = 1, max = 60)
	@ConfigItem(
		keyName = "statisticsInterval",
		name = "Tracking Interval (seconds)",
		description = "How often to sample statistics data",
		section = statisticsSection
	)
	default int statisticsInterval()
	{
		return 3;
	}

	@Range(min = 1, max = 20)
	@ConfigItem(
		keyName = "playerCountRadius",
		name = "Player Count Radius",
		description = "Tile radius for counting nearby players",
		section = statisticsSection
	)
	default int playerCountRadius()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "enableSessionPruning",
		name = "Prune Old Sessions",
		description = "Automatically delete the oldest local sessions once the count below is exceeded. "
			+ "Disabled by default so sessions are never lost. If Server Sync is also enabled, a session "
			+ "is only pruned after it has been successfully synced to the server.",
		section = statisticsSection
	)
	default boolean enableSessionPruning()
	{
		return false;
	}

	@Range(min = 1, max = 10000)
	@ConfigItem(
		keyName = "maxStoredSessions",
		name = "Sessions Kept On Disk",
		description = "Maximum number of finished sessions kept in local history before pruning kicks in. Only takes effect when Prune Old Sessions is enabled.",
		section = statisticsSection
	)
	default int maxStoredSessions()
	{
		return 200;
	}

	@Range(min = 0, max = 600)
	@ConfigItem(
		keyName = "minimumSessionDuration",
		name = "Min Session Duration (seconds)",
		description = "Sessions shorter than this duration will be discarded",
		section = statisticsSection
	)
	default int minimumSessionDuration()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "enableGriefPrevention",
		name = "Enable Grief Prevention",
		description = "Show warning overlay if Accept Aid is on or Private Chat is set to All",
		section = statisticsSection
	)
	default boolean enableGriefPrevention()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoDetectSpell",
		name = "Auto-detect Spell",
		description = "Automatically detect the spell being cast based on XP gained. Disable to use manual selection below.",
		section = statisticsSection,
		position = 10
	)
	default boolean autoDetectSpell()
	{
		return true;
	}

	@ConfigItem(
		keyName = "selectedSpell",
		name = "Splash Spell",
		description = "Select the spell you are using for splashing (only used when auto-detect is disabled)",
		section = statisticsSection,
		position = 11
	)
	default SplashSpell selectedSpell()
	{
		return SplashSpell.FIRE_STRIKE;
	}

	// ==================== Overall Statistics Panel ====================

	@ConfigSection(
		name = "Overall Statistics Panel",
		description = "Configure which fields to show in the overall statistics panel",
		position = 30,
		closedByDefault = true
	)
	String overallStatsSection = "overallStats";

	@ConfigItem(
		keyName = "showOverallStats",
		name = "Show Overall Statistics",
		description = "Enable the overall statistics panel",
		section = overallStatsSection,
		position = 0
	)
	default boolean showOverallStats()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overallStatFields",
		name = "Visible Fields",
		description = "Select which fields to display in the overall statistics panel",
		section = overallStatsSection,
		position = 1
	)
	default Set<OverallStatField> overallStatFields()
	{
		return EnumSet.allOf(OverallStatField.class);
	}

	// ==================== Current Session Panel ====================

	@ConfigSection(
		name = "Current Session Panel",
		description = "Configure which fields to show in the current session panel",
		position = 31,
		closedByDefault = true
	)
	String currentSessionSection = "currentSession";

	@ConfigItem(
		keyName = "showCurrentSession",
		name = "Show Current Session",
		description = "Enable the current session panel",
		section = currentSessionSection,
		position = 0
	)
	default boolean showCurrentSession()
	{
		return true;
	}

	@ConfigItem(
		keyName = "currentSessionFields",
		name = "Visible Fields",
		description = "Select which fields to display in the current session panel",
		section = currentSessionSection,
		position = 1
	)
	default Set<SessionStatField> currentSessionFields()
	{
		return EnumSet.allOf(SessionStatField.class);
	}

	// ==================== Session History Panel ====================

	@ConfigSection(
		name = "Session History Panel",
		description = "Configure which fields to show in the session history panel",
		position = 32,
		closedByDefault = true
	)
	String sessionHistorySection = "sessionHistory";

	@ConfigItem(
		keyName = "showSessionHistory",
		name = "Show Session History",
		description = "Enable the session history panel",
		section = sessionHistorySection,
		position = 0
	)
	default boolean showSessionHistory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sessionHistoryFields",
		name = "Visible Fields",
		description = "Select which fields to display in the session history panel",
		section = sessionHistorySection,
		position = 1
	)
	default Set<SessionStatField> sessionHistoryFields()
	{
		return EnumSet.allOf(SessionStatField.class);
	}

	@Range(min = 0, max = 3600)
	@ConfigItem(
		keyName = "sessionResumeWindowSeconds",
		name = "Session Resume Window (seconds)",
		description = "How long after a session ends it can be resumed when the same player returns (e.g. after using dragon spear or the 6-hour logout). Set to 0 to disable.",
		section = statisticsSection,
		position = 12
	)
	default int sessionResumeWindowSeconds()
	{
		return 600; // 10 minutes
	}

	@ConfigItem(
		keyName = "safetyModeEnabled",
		name = "Safety Mode",
		description = "Enable safety mode to prevent actions that lose knight aggro"
	)
	default boolean safetyModeEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "safetyModeHotkey",
		name = "Safety Mode Hotkey",
		description = "Hotkey to toggle safety mode (default: Numlock *)"
	)
	default ModifierlessKeybind safetyModeHotkey()
	{
		return new ModifierlessKeybind(KeyEvent.VK_MULTIPLY, 0);
	}

	@ConfigItem(
		keyName = "toggleOverlaysHotkey",
		name = "Toggle Overlays Hotkey",
		description = "Hotkey to show/hide all Splash Helper overlays (default: Numlock /)"
	)
	default ModifierlessKeybind toggleOverlaysHotkey()
	{
		return new ModifierlessKeybind(KeyEvent.VK_DIVIDE, 0);
	}

	// ==================== Server Sync ====================

	@ConfigSection(
		name = "Server Sync",
		description = "Sync live session data with a Splash Helper server via WebSocket",
		position = 40,
		closedByDefault = true
	)
	String serverSyncSection = "serverSync";

	@ConfigItem(
		keyName = "enableServerSync",
		name = "Enable Server Sync",
		description = "Connect to a third-party Splash Helper server and stream live session data. "
			+ "This sends your account username and session statistics (spell used, world, magic XP, "
			+ "rune usage and cost, spells cast, knight movements, nearby player counts and timestamps) "
			+ "to the configured server. Leave disabled if you do not want any data sent externally.",
		warning = "Enabling Server Sync connects to a third-party server (splasher.help by default) and "
			+ "sends your account username and splash session statistics — including the spell used, world, "
			+ "magic XP, rune usage and cost, spells cast, knight movements, nearby player counts and "
			+ "timestamps. No data is sent while this is disabled. Are you sure you want to enable it?",
		section = serverSyncSection,
		position = 0
	)
	default boolean enableServerSync()
	{
		return false;
	}

	@ConfigItem(
		keyName = "serverUrl",
		name = "Server URL",
		description = "WebSocket URL of the Splash Helper server",
		section = serverSyncSection,
		position = 1
	)
	default String serverUrl()
	{
		return "wss://api.splasher.help";
	}

	// ==================== Sticky Knight Guide ====================

	@ConfigSection(
		name = "Sticky Knight Guide",
		description = "Step-by-step guide for setting up a sticky knight",
		position = 50,
		closedByDefault = true
	)
	String guideSection = "guide";

	@ConfigItem(
		keyName = "guideStartHotkey",
		name = "Start/Stop Guide",
		description = "Hotkey to start or stop the sticky knight setup guide",
		section = guideSection,
		position = 0
	)
	default Keybind guideStartHotkey()
	{
		return new Keybind(KeyEvent.VK_G, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "guideNextHotkey",
		name = "Next / Skip Step",
		description = "Hotkey to acknowledge the requirements screen, or skip the current step",
		section = guideSection,
		position = 1
	)
	default Keybind guideNextHotkey()
	{
		return new Keybind(KeyEvent.VK_PERIOD, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "guideBackHotkey",
		name = "Previous Step",
		description = "Hotkey to go back one step",
		section = guideSection,
		position = 2
	)
	default Keybind guideBackHotkey()
	{
		return new Keybind(KeyEvent.VK_COMMA, InputEvent.CTRL_DOWN_MASK);
	}

	@Range(min = 3, max = 120)
	@ConfigItem(
		keyName = "guideStepTimeoutSeconds",
		name = "Stuck Hint Delay (seconds)",
		description = "How long on a step before showing the 'you can go back' hint",
		section = guideSection,
		position = 3
	)
	default int guideStepTimeoutSeconds()
	{
		return 15;
	}

	@Range(min = 4, max = 28)
	@ConfigItem(
		keyName = "guideArrowSize",
		name = "Arrow Size",
		description = "Size (in pixels) of the highlight arrows drawn above tiles, NPCs and interface elements",
		section = guideSection,
		position = 4
	)
	default int guideArrowSize()
	{
		return 12;
	}

	@ConfigItem(
		keyName = "requirementsAcknowledged",
		name = "Requirements Acknowledged",
		description = "Whether the setup requirements have been acknowledged. Uncheck to show the requirements screen again on the next start.",
		section = guideSection,
		position = 5
	)
	default boolean requirementsAcknowledged()
	{
		return false;
	}

	@ConfigItem(
		keyName = "requirementsAcknowledged",
		name = "",
		description = ""
	)
	void setRequirementsAcknowledged(boolean value);
}

package xyz.peppie.splashhelper.model;

/**
 * Alert level of the splash timer, derived from the remaining time and the
 * configured warning/critical thresholds. Drives both the timer overlay text
 * color and the visual notification tint so they always change together.
 */
public enum TimerAlertLevel
{
	/** No timer running. */
	NONE,
	/** Timer running with more than the warning threshold remaining. */
	NORMAL,
	/** At or below the warning threshold (orange). */
	WARNING,
	/** At or below the critical threshold (red). */
	CRITICAL,
	/** Timer has expired. */
	EXPIRED
}

package xyz.peppie.splashhelper.model;

import java.time.Instant;
import java.util.UUID;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Server-ready session data structure for persistence.
 * Includes UUID and timestamps for server synchronization.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class PersistedSession
{
	/**
	 * Unique identifier for this session (for server sync)
	 */
	private String sessionId;

	/**
	 * When this session was created (for server ordering)
	 */
	private long createdTimestamp;

	/**
	 * When this session was finalized
	 */
	private long finalizedTimestamp;

	/**
	 * Whether this session has been synced to server
	 */
	private boolean syncedToServer;

	/**
	 * The actual session data
	 */
	private SplashSession session;

	/**
	 * Create a new persisted session from a SplashSession
	 */
	public static PersistedSession fromSession(SplashSession session)
	{
		return PersistedSession.builder()
			.sessionId(UUID.randomUUID().toString())
			.createdTimestamp(session.getStartTime().toEpochMilli())
			.finalizedTimestamp(session.getEndTime() != null ? session.getEndTime().toEpochMilli() : Instant.now().toEpochMilli())
			.syncedToServer(session.isSynced())
			.session(session)
			.build();
	}
}

package xyz.peppie.splashhelper.model;

import java.util.ArrayList;
import java.util.List;
import lombok.Getter;

/**
 * Fixed-size time series of player counts for one session.
 *
 * Samples are aggregated into time buckets of {@link #bucketSeconds} width,
 * storing the rounded average per bucket. When a session outgrows
 * {@link #MAX_BUCKETS}, adjacent buckets are merged and the bucket width
 * doubles, so any session length fits in a bounded, graph-friendly payload
 * (≤360 ints regardless of duration). Buckets with no samples (e.g. a logout
 * gap inside the resume window) are stored as {@link #NO_DATA} so graphs can
 * render them as breaks instead of fake values.
 */
public class PlayerCountSeries
{
	public static final int NO_DATA = -1;
	private static final int MAX_BUCKETS = 360;
	private static final int INITIAL_BUCKET_SECONDS = 10;

	@Getter
	private int bucketSeconds = INITIAL_BUCKET_SECONDS;

	private List<Integer> buckets = new ArrayList<>();

	// In-progress bucket accumulation; not persisted (finalized sessions are sealed)
	private transient int pendingIndex = -1;
	private transient long pendingSum = 0;
	private transient int pendingCount = 0;

	/**
	 * Record one player-count sample taken at the given offset from session start.
	 */
	public void addSample(long elapsedSeconds, int count)
	{
		if (elapsedSeconds < 0)
		{
			return;
		}

		int index = (int) (elapsedSeconds / bucketSeconds);
		while (index >= MAX_BUCKETS)
		{
			compress();
			index = (int) (elapsedSeconds / bucketSeconds);
		}

		if (index == pendingIndex)
		{
			pendingSum += count;
			pendingCount++;
		}
		else
		{
			flushPending();
			pendingIndex = index;
			pendingSum = count;
			pendingCount = 1;
		}
	}

	/**
	 * Flush the in-progress bucket. Call when the session is finalized.
	 */
	public void seal()
	{
		flushPending();
	}

	/**
	 * Snapshot of the finalized buckets (including the in-progress one), for
	 * serialization to the server. Never null.
	 */
	public List<Integer> getBuckets()
	{
		List<Integer> snapshot = new ArrayList<>(buckets);
		if (pendingCount > 0)
		{
			while (snapshot.size() < pendingIndex)
			{
				snapshot.add(NO_DATA);
			}
			snapshot.add((int) Math.round((double) pendingSum / pendingCount));
		}
		return snapshot;
	}

	private void flushPending()
	{
		if (pendingCount == 0)
		{
			return;
		}
		// Pad any skipped buckets (no samples arrived for them) as gaps
		while (buckets.size() < pendingIndex)
		{
			buckets.add(NO_DATA);
		}
		buckets.add((int) Math.round((double) pendingSum / pendingCount));
		pendingIndex = -1;
		pendingSum = 0;
		pendingCount = 0;
	}

	/**
	 * Halve the resolution: merge adjacent bucket pairs and double the bucket width.
	 */
	private void compress()
	{
		flushPending();
		List<Integer> merged = new ArrayList<>((buckets.size() + 1) / 2);
		for (int i = 0; i < buckets.size(); i += 2)
		{
			int a = buckets.get(i);
			int b = (i + 1 < buckets.size()) ? buckets.get(i + 1) : NO_DATA;
			if (a == NO_DATA && b == NO_DATA)
			{
				merged.add(NO_DATA);
			}
			else if (a == NO_DATA)
			{
				merged.add(b);
			}
			else if (b == NO_DATA)
			{
				merged.add(a);
			}
			else
			{
				merged.add((int) Math.round((a + b) / 2.0));
			}
		}
		buckets = merged;
		bucketSeconds *= 2;
	}
}

package xyz.peppie.splashhelper.model;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum TargetNpc
{
	KNIGHT_OF_ARDOUGNE("Knight of Ardougne"),
	RAT("Rat"),
	GUARD("Guard");

	private final String npcName;

	@Override
	public String toString()
	{
		return npcName;
	}
}

package xyz.peppie.splashhelper.model;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import lombok.Setter;

@Getter
public class SplashSession
{
	// Static fields (set once at session start)
	private final String playerName;
	private SplashSpell spell;
	private int runeCostPerCast;
	private final Instant startTime;
	@Setter
	private Instant logoutTime;
	@Setter
	private int world;
	@Setter
	private boolean stickyKnight;

	// Dynamic fields (updated during session)
	@Setter
	private int spellsCast = 0;
	@Setter
	private int startMagicXp;
	@Setter
	private int currentMagicXp;
	@Setter
	private int knightMovements = 0;
	// Count of nearby players observed dying during this session
	@Setter
	private int playerDeaths = 0;
	// Count of nearby players observed reaching level 99 in a skill during this session
	@Setter
	private int level99Count = 0;
	@Setter
	private Instant endTime = null;

	// Player tracking (transient - not persisted)
	private transient final Set<String> pickpocketers = new HashSet<>();
	// Running mean for player count: O(1) memory, exact average over any session length.
	private transient long playerCountSum = 0;
	private transient long playerCountSampleN = 0;
	// Bounded, downsampled player-count-over-time series (persisted; used for server graphs)
	private PlayerCountSeries playerCountSeries = new PlayerCountSeries();
	@Setter
	private int highestPlayerCount = 0;

	// Derived statistics for persistence
	@Setter
	private int averagePlayerCount = 0;
	@Setter
	private int pickpocketerCount = 0;
	// Live snapshot, updated every sample: nearby players right now (as opposed to
	// highest/averagePlayerCount, which summarize the whole session).
	@Setter
	private int currentPlayerCount = 0;

	// Rune tracking
	@Setter
	private int startingRuneCount = 0;
	@Setter
	private int currentRuneCount = 0;
	private final Map<Integer, Integer> runeUsageMap = new HashMap<>();  // ItemId -> Total amount used
	@Setter
	private long runeCostGp = 0;  // Total GP cost of runes used

	// Whether this finalized session has been successfully sent to the sync server.
	// Defaults to false (and stays false when server sync is off, which is fine since
	// pruning only consults this flag while server sync is enabled).
	@Setter
	private boolean synced = false;

	public SplashSession(String playerName, SplashSpell spell, Instant logoutTime, int world, boolean stickyKnight, int startMagicXp)
	{
		this.playerName = playerName;
		this.spell = spell;
		this.runeCostPerCast = spell != null ? spell.getTotalRuneCost() : 0;
		this.startTime = Instant.now();
		this.logoutTime = logoutTime;
		this.world = world;
		this.stickyKnight = stickyKnight;
		this.startMagicXp = startMagicXp;
		this.currentMagicXp = startMagicXp;
	}

	public void setSpell(SplashSpell newSpell)
	{
		this.spell = newSpell;
		this.runeCostPerCast = newSpell != null ? newSpell.getTotalRuneCost() : 0;
	}

	public long getSessionDurationSeconds()
	{
		Instant end = endTime != null ? endTime : Instant.now();
		return java.time.Duration.between(startTime, end).getSeconds();
	}

	public int getMagicXpGained()
	{
		return currentMagicXp - startMagicXp;
	}

	public double getXpPerHour()
	{
		long seconds = getSessionDurationSeconds();
		if (seconds <= 0)
		{
			return 0;
		}
		return (getMagicXpGained() * 3600.0) / seconds;
	}

	public void addPickpocketer(String playerName)
	{
		if (playerName != null && !playerName.isEmpty())
		{
			pickpocketers.add(playerName);
			pickpocketerCount = pickpocketers.size();
		}
	}

	public void addPlayerCountSample(int count)
	{
		playerCountSampleN++;
		playerCountSum += count;
		if (count > highestPlayerCount)
		{
			highestPlayerCount = count;
		}
		averagePlayerCount = (int) Math.round((double) playerCountSum / playerCountSampleN);

		if (playerCountSeries == null)
		{
			// Sessions loaded from an older on-disk format have no series
			playerCountSeries = new PlayerCountSeries();
		}
		playerCountSeries.addSample(java.time.Duration.between(startTime, Instant.now()).getSeconds(), count);
	}

	public double getAveragePlayerCount()
	{
		return averagePlayerCount;
	}

	public void incrementSpellsCast()
	{
		spellsCast++;
	}

	public void incrementKnightMovements()
	{
		knightMovements++;
	}

	public void incrementPlayerDeaths()
	{
		playerDeaths++;
	}

	public void incrementLevel99Count()
	{
		level99Count++;
	}

	/**
	 * Add rune usage for a single cast to the accumulated total.
	 * This allows tracking mixed spell usage without recalculating.
	 * @param runesUsedThisCast List of [itemId, amount] pairs for this cast
	 * @param costGp GP cost of runes used in this cast
	 */
	public void addRuneUsageForCast(List<int[]> runesUsedThisCast, long costGp)
	{
		if (runesUsedThisCast == null || runesUsedThisCast.isEmpty())
		{
			return;
		}

		// Accumulate rune usage using Map (no reference issues)
		for (int[] runeUsage : runesUsedThisCast)
		{
			int itemId = runeUsage[0];
			int amount = runeUsage[1];

			// Simply add to the map - Map.put handles both new and existing entries
			runeUsageMap.put(itemId, runeUsageMap.getOrDefault(itemId, 0) + amount);
		}

		// Accumulate cost
		runeCostGp += costGp;
	}

	/**
	 * Get actual rune usage as List<int[]> for compatibility with existing code.
	 * @return List of [itemId, totalAmount] pairs
	 */
	public List<int[]> getActualRuneUsage()
	{
		List<int[]> result = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : runeUsageMap.entrySet())
		{
			result.add(new int[]{entry.getKey(), entry.getValue()});
		}
		return result;
	}

	/**
	 * Un-finalize this session so it can be resumed after a brief interruption.
	 */
	public void resume()
	{
		this.endTime = null;
	}

	public boolean isActive()
	{
		return endTime == null;
	}
}

