		String message = safetyModeEnabled ? 
			"<col=00ff00>Safety mode ENABLED</col>" : 
			"<col=ff0000>Safety mode DISABLED</col>";
		clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null));
