	 * Toggle visibility of all Splash Helper overlays on/off.
	 */
	public void toggleOverlaysVisible()
	{
		overlaysVisible = !overlaysVisible;
		log.debug("Overlays toggled: {}", overlaysVisible ? "SHOWN" : "HIDDEN");

		if (overlaysVisible)
		{
			overlayManager.add(overlay);
			overlayManager.add(boundaryOverlay);
			overlayManager.add(visualNotificationOverlay);
			overlayManager.add(griefPreventionOverlay);
			overlayManager.add(magicBonusWarningOverlay);
			overlayManager.add(safetyModeOverlay);
			overlayManager.add(guideSceneOverlay);
			overlayManager.add(guideWidgetOverlay);
			overlayManager.add(guidePanelOverlay);
		}
		else
		{
			overlayManager.remove(overlay);
			overlayManager.remove(boundaryOverlay);
			overlayManager.remove(visualNotificationOverlay);
			overlayManager.remove(griefPreventionOverlay);
			overlayManager.remove(magicBonusWarningOverlay);
			overlayManager.remove(safetyModeOverlay);
			overlayManager.remove(guideSceneOverlay);
			overlayManager.remove(guideWidgetOverlay);
			overlayManager.remove(guidePanelOverlay);
		}

		String message = overlaysVisible ?
			"<col=00ff00>Splash Helper overlays SHOWN</col>" :
			"<col=ff0000>Splash Helper overlays HIDDEN</col>";
		clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null));
	}

	/**
	 * Key listener for the toggle-all-overlays hotkey.
	 */
	private final KeyListener toggleOverlaysKeyListener = new KeyListener()
	{
		@Override
		public void keyTyped(KeyEvent e)
		{
		}

		@Override
		public void keyPressed(KeyEvent e)
		{
			ModifierlessKeybind hotkey = config.toggleOverlaysHotkey();
			if (hotkey.matches(e))
			{
				toggleOverlaysVisible();
				e.consume();
			}
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
		}
	};

	/**
	 * Global key listener that mirrors OSRS's combat idle timer: typing and
	 * keyboard camera movement (arrow keys) reset it, so they reset the splash
	 * timer too. Observation only — events are never consumed or synthesized.
	 */
	private final KeyListener timerResetKeyListener = new KeyListener()
	{
		@Override
		public void keyTyped(KeyEvent e)
		{
		}

		@Override
		public void keyPressed(KeyEvent e)
		{
			// The safety-mode and toggle-overlays hotkeys are consumed by their
			// own listeners and never reach the game, so they must not reset the timer.
			if (config.safetyModeHotkey().matches(e) || config.toggleOverlaysHotkey().matches(e))
			{
				return;
			}
			// resetTimer() no-ops when the timer is not running, so idle
			// typing (e.g. in the bank) never starts a timer or session.
			clientThread.invokeLater(SplashHelperPlugin.this::resetTimer);
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
		}
	};

	/**
	 * Global mouse listener that mirrors OSRS's combat idle timer: right-clicking
	 * anywhere on the game window (even just to open a context menu, without
	 * selecting an option) resets it, so it resets the splash timer too.
	 * Observation only — events are never consumed.
	 */
	private final MouseListener timerResetMouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			if (e.getButton() == MouseEvent.BUTTON3)
			{
				// resetTimer() no-ops when the timer is not running, so idle
				// right-clicks (e.g. in the bank) never start a timer or session.
				clientThread.invokeLater(SplashHelperPlugin.this::resetTimer);
			}
			return e;
		}
	};
}

package xyz.peppie.splashhelper.service;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import xyz.peppie.splashhelper.SplashHelperConfig;

import java.awt.TrayIcon;

/**
 * Service for handling all notification logic.
 */
@Slf4j
@Singleton
public class NotificationService
{
	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	@Inject
	private SplashHelperConfig config;

	private boolean notificationsMuted = false;
	private VisualNotificationCallback visualNotificationCallback;

	public interface VisualNotificationCallback
	{
		void triggerVisualNotification();
	}

	public void setVisualNotificationCallback(VisualNotificationCallback callback)
	{
		this.visualNotificationCallback = callback;
	}

	/**
	 * Send a timer notification.
	 */
	public void sendTimerNotification(String message)
	{
		if (!config.enableTimerNotification())
		{
			return;
		}
		if (notificationsMuted)
		{
			return;
		}
		sendNotificationInternal(message);
	}

	/**
	 * Send a boundary notification.
	 */
	public void sendBoundaryNotification(String message)
	{
		if (!config.enableBoundaryNotification())
		{
			return;
		}
		if (notificationsMuted)
		{
			return;
		}
		sendNotificationInternal(message);
	}

	/**
	 * Send an HP notification.
	 */
	public void sendHpNotification(String message)
	{
		if (!config.enableHpNotification())
		{
			return;
		}
		if (notificationsMuted)
		{
			return;
		}
		sendNotificationInternal(message);
	}

	/**
	 * Send a generic notification.
	 */
	public void sendNotification(String message)
	{
		sendNotificationInternal(message);
	}

	/**
	 * Mute all notifications.
	 */
	public void muteNotifications()
	{
		notificationsMuted = true;
	}

	/**
	 * Unmute all notifications.
	 */
	public void unmuteNotifications()
	{
		notificationsMuted = false;
	}

	/**
	 * Check if notifications are muted.
	 */
	public boolean areNotificationsMuted()
	{
		return notificationsMuted;
	}

	/**
	 * Internal method to send notification.
	 */
	private void sendNotificationInternal(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "Splash Helper", message, null);

		if (config.enableVisualNotification())
		{
			// Trigger visual notification overlay in main plugin
			if (visualNotificationCallback != null)
			{
				visualNotificationCallback.triggerVisualNotification();
			}
			log.debug("Visual notification triggered: {}", message);
		}

		if (config.enableSoundNotification())
		{
			// Defer to the user's own RuneLite-wide Settings > Notifications config
			// (sound type, volume, timeout, tray, request-focus behavior, send-when-focused)
			// instead of forcing our own opinionated Notification object - this is what
			// actually respects the user's "send notifications when focused" preference.
			notifier.notify(message, TrayIcon.MessageType.WARNING);
		}
	}
}

package xyz.peppie.splashhelper.service;

import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Service responsible for tracking players near the knight,
 * particularly pickpocketers who may affect splashing.
 */
@Singleton
public class PlayerTracker
{
	private final Set<String> pickpocketers = new HashSet<>();

	@Inject
	public PlayerTracker()
	{
	}

	/**
	 * Reset all tracking data.
	 */
	public void reset()
	{
		pickpocketers.clear();
	}

	/**
	 * Add a player to the pickpocketer set.
	 * @return true if this is a new pickpocketer
	 */
	public boolean addPickpocketer(String playerName)
	{
		if (playerName == null || playerName.isEmpty())
		{
			return false;
		}
		return pickpocketers.add(playerName);
	}

	/**
	 * Get all tracked pickpocketers.
	 */
	public Set<String> getPickpocketers()
	{
		return new HashSet<>(pickpocketers);
	}
}

