	/**
	 * Whether a recently finalized session is still within its resume window.
	 */
	public boolean hasResumableSession()
	{
		return resumableSession != null && System.currentTimeMillis() < resumableSessionExpiryMs;
	}

	/**
	 * Milliseconds until the resume window closes, or 0 if none is open.
	 */
	public long getResumableSessionRemainingMs()
	{
		if (!hasResumableSession())
		{
			return 0;
		}
		return Math.max(0, resumableSessionExpiryMs - System.currentTimeMillis());
	}

	/**
	 * Poll whether a pending resumable session's window has lapsed and, if so, finalize
	 * it to the backend. Intended to be called regularly (e.g. every game tick) so
	 * SESSION_END is still sent even if the player never returns to start a new session.
	 */
	public void checkResumableSessionExpiry()
	{
		if (resumableSession != null && System.currentTimeMillis() >= resumableSessionExpiryMs)
		{
			expireResumableSession();
		}
	}

	/**
	 * Finalize any pending resumable session to the backend right now, without waiting
	 * for its window to lapse naturally. Used when the window expiry is detected early
	 * (e.g. missed on the same tick a new session would have resumed it) and on plugin
	 * shutdown, where the resume window can no longer be observed expiring on its own.
	 */
	public void expireResumableSession()
	{
		SplashSession session = resumableSession;
		resumableSession = null;
		resumableSessionExpiryMs = 0;
		if (session != null && sessionFinalizedCallback != null)
		{
			sessionFinalizedCallback.accept(session);
		}
	}

	/**
	 * Save session history to the current user's file on disk.
	 * If pruning is enabled, removes the oldest sessions beyond the configured on-disk
	 * retention count. A session is only ever pruned once it is confirmed synced to the
	 * server (or immediately if server sync is disabled), so enabling sync never races
	 * with pruning to lose data that hasn't reached the server yet.
	 */
	private void saveSessionHistory()
	{
		if (currentHistoryUsername == null)
		{
			log.debug("Skipping session history save - no user loaded yet");
			return;
		}

		if (config.enableSessionPruning())
		{
			pruneSessionHistory();
		}

		List<PersistedSession> persistedSessions = new ArrayList<>();
		for (SplashSession session : sessionHistory)
		{
			persistedSessions.add(PersistedSession.fromSession(session));
		}

		writePersistedSessionsToFile(historyFileFor(currentHistoryUsername), persistedSessions);
		log.debug("Saved {} sessions to persistent storage for {}", sessionHistory.size(), currentHistoryUsername);
	}

	/**
	 * Load history for {@link #currentHistoryUsername} from its per-user file into {@link #sessionHistory}.
	 * Deduplicates sessions by comparing actual session data to handle corrupted history files.
	 */
	private void loadHistoryForCurrentUser()
	{
		sessionHistory.clear();

		List<PersistedSession> persistedSessions = readPersistedSessionsFromFile(historyFileFor(currentHistoryUsername));

		// Deduplicate by session content (not ID, since duplicates can have different UUIDs)
		Set<String> seenSessionHashes = new HashSet<>();
		List<PersistedSession> dedupedSessions = new ArrayList<>();
		boolean hadDuplicates = false;

		for (PersistedSession persisted : persistedSessions)
		{
			if (persisted.getSession() != null)
			{
				SplashSession session = persisted.getSession();
				// Hash based on the actual session data (player, timestamps, stats)
				// This catches exact duplicates even if they have different session IDs
				String sessionHash = createSessionHash(session);

				if (!seenSessionHashes.add(sessionHash))
				{
					// Duplicate found (same data, possibly different ID), skip it
					hadDuplicates = true;
					log.debug("Skipped duplicate session data during load: {} from {} to {}",
						session.getPlayerName(), session.getStartTime(), session.getEndTime());
				}
				else
				{
					sessionHistory.add(session);
					dedupedSessions.add(persisted);
				}
			}
		}

		// If we found and removed duplicates, rewrite the file to clean it up
		if (hadDuplicates)
		{
			log.info("Detected {} duplicate session(s) in history file for {}; cleaning up...",
				persistedSessions.size() - dedupedSessions.size(), currentHistoryUsername);
			writePersistedSessionsToFile(historyFileFor(currentHistoryUsername), dedupedSessions);
		}

		if (config.enableSessionPruning())
		{
			pruneSessionHistory();
		}
	}

	/**
	 * Create a hash of session data for duplicate detection.
	 * Two sessions with identical data (player, timestamps, stats) will produce the same hash.
	 */
	private String createSessionHash(SplashSession session)
	{
		// Use player name, start time, and end time to identify unique sessions
		// This detects exact duplicates even if they have different session IDs
		return session.getPlayerName() + "|" +
			   session.getStartTime() + "|" +
			   session.getEndTime() + "|" +
			   session.getSpellsCast() + "|" +
			   session.getStartMagicXp();
	}

	/**
	 * The per-user history file for a given RSN. Usernames are case-insensitive in-game,
	 * so the filename is normalized to avoid two files for the same account.
	 */
	private static File historyFileFor(String username)
	{
		return new File(HISTORY_DIR, "session-history-" + sanitizeUsernameForFilename(username) + ".json");
	}

	private static String sanitizeUsernameForFilename(String username)
	{
		String normalized = username.trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "_");
		return normalized.isEmpty() ? "unknown" : normalized;
	}

	/**
	 * Read a list of persisted sessions from a JSON file, or an empty list if it doesn't
	 * exist, is empty, or fails to parse.
	 */
	private List<PersistedSession> readPersistedSessionsFromFile(File file)
	{
		try
		{
			if (!file.isFile())
			{
				return new ArrayList<>();
			}

			String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
			if (json.trim().isEmpty())
			{
				return new ArrayList<>();
			}

			java.lang.reflect.Type type = new TypeToken<List<PersistedSession>>(){}.getType();
			List<PersistedSession> persistedSessions = gson.fromJson(json, type);
			return persistedSessions != null ? persistedSessions : new ArrayList<>();
		}
		catch (Exception e)
		{
			log.error("Failed to read session history from {}", file, e);
			return new ArrayList<>();
		}
	}

	/**
	 * Write a list of persisted sessions to a JSON file, via a temp file + atomic move so a
	 * crash mid-write can't leave a corrupt/truncated history file behind.
	 */
	private void writePersistedSessionsToFile(File file, List<PersistedSession> persistedSessions)
	{
		try
		{
			File parentDir = file.getParentFile();
			Files.createDirectories(parentDir.toPath());

			String json = gson.toJson(persistedSessions);
			File tempFile = File.createTempFile("session-history", ".tmp", parentDir);
			Files.write(tempFile.toPath(), json.getBytes(StandardCharsets.UTF_8));
			Files.move(tempFile.toPath(), file.toPath(),
				StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (IOException e)
		{
			log.error("Failed to write session history to {}", file, e);
		}
	}

	/**
	 * One-time migration of session history from older storage schemes (RSProfile config,
	 * then a single shared local file) into the current per-user local files. Each legacy
	 * session is routed to the file matching its own recorded player name, since a single
	 * legacy blob may contain sessions for more than one account.
	 */
	private void migrateLegacyHistory()
	{
		migrateLegacyConfigHistory();
		migrateLegacySharedFileHistory();
	}

	private void migrateLegacyConfigHistory()
	{
		try
		{
			String json = configManager.getConfiguration(LEGACY_CONFIG_GROUP, LEGACY_CONFIG_KEY);
			if (json == null || json.trim().isEmpty())
			{
				return;
			}

			java.lang.reflect.Type type = new TypeToken<List<PersistedSession>>(){}.getType();
			List<PersistedSession> legacySessions = gson.fromJson(json, type);
			if (legacySessions != null && !legacySessions.isEmpty())
			{
				distributeSessionsToUserFiles(legacySessions);
				log.info("Migrated {} session(s) from RSProfile config storage to per-user local files", legacySessions.size());
			}

			configManager.unsetConfiguration(LEGACY_CONFIG_GROUP, LEGACY_CONFIG_KEY);
		}
		catch (Exception e)
		{
			log.error("Failed to migrate legacy config-based session history", e);
		}
	}

	private void migrateLegacySharedFileHistory()
	{
		if (!LEGACY_SHARED_HISTORY_FILE.isFile())
		{
			return;
		}

		try
		{
			List<PersistedSession> legacySessions = readPersistedSessionsFromFile(LEGACY_SHARED_HISTORY_FILE);
			if (!legacySessions.isEmpty())
			{
				distributeSessionsToUserFiles(legacySessions);
				log.info("Migrated {} session(s) from shared local history file to per-user files", legacySessions.size());
			}
		}
		finally
		{
			try
			{
				Files.deleteIfExists(LEGACY_SHARED_HISTORY_FILE.toPath());
			}
			catch (IOException e)
			{
				log.error("Failed to remove migrated legacy shared history file", e);
			}
		}
	}

	/**
	 * Merge a batch of legacy persisted sessions into the appropriate per-user files,
	 * grouped by each session's own recorded player name, deduplicated by session ID.
	 */
	private void distributeSessionsToUserFiles(List<PersistedSession> legacySessions)
	{
		Map<String, List<PersistedSession>> byUser = new LinkedHashMap<>();
		for (PersistedSession persisted : legacySessions)
		{
			String name = persisted.getSession() != null ? persisted.getSession().getPlayerName() : null;
			String key = (name == null || name.trim().isEmpty()) ? "unknown" : name.trim();
			byUser.computeIfAbsent(key, k -> new ArrayList<>()).add(persisted);
		}

		for (Map.Entry<String, List<PersistedSession>> entry : byUser.entrySet())
		{
			File targetFile = historyFileFor(entry.getKey());
			List<PersistedSession> merged = readPersistedSessionsFromFile(targetFile);

			Set<String> existingIds = new HashSet<>();
			for (PersistedSession persisted : merged)
			{
				if (persisted.getSessionId() != null)
				{
					existingIds.add(persisted.getSessionId());
				}
			}

			for (PersistedSession persisted : entry.getValue())
			{
				if (persisted.getSessionId() == null || existingIds.add(persisted.getSessionId()))
				{
					merged.add(persisted);
				}
			}

			merged.sort(Comparator.comparingLong(PersistedSession::getCreatedTimestamp));
			prunePersistedSessions(merged);

			writePersistedSessionsToFile(targetFile, merged);
		}
	}

	/**
	 * Same retention policy as {@link #pruneSessionHistory()} (opt-in, sync-aware), applied
	 * to an arbitrary oldest-first list of {@link PersistedSession} rather than the live
	 * {@link #sessionHistory} field. Used when merging migrated history for an account that
	 * may not be the currently loaded user.
	 */
	private void prunePersistedSessions(List<PersistedSession> sessions)
	{
		if (!config.enableSessionPruning())
		{
			return;
		}

		int maxStored = Math.max(1, config.maxStoredSessions());
		boolean requireSync = config.enableServerSync();
		while (sessions.size() > maxStored)
		{
			PersistedSession oldest = sessions.get(0);
			if (requireSync && !oldest.isSyncedToServer())
			{
				break;
			}
			sessions.remove(0);
		}
	}

	/**
	 * Trim {@link #sessionHistory} down to the configured retention count, oldest first.
	 * A session is only removed once it is safe to lose: either server sync is disabled
	 * entirely, or the session has been confirmed synced to the server. Pruning stops as
	 * soon as it reaches a session that isn't synced yet, so unsynced sessions are never
	 * silently deleted out from under an in-progress (or not-yet-attempted) sync.
	 */
	private void pruneSessionHistory()
	{
		int maxStored = Math.max(1, config.maxStoredSessions());
		boolean requireSync = config.enableServerSync();
		while (sessionHistory.size() > maxStored)
		{
			SplashSession oldest = sessionHistory.get(0);
			if (requireSync && !oldest.isSynced())
			{
				log.debug("Pausing session pruning: oldest session for {} is not yet synced to server", oldest.getPlayerName());
				break;
			}
			sessionHistory.remove(0);
		}
	}

	/**
	 * Finalized sessions in history that have not yet been confirmed synced to the server.
	 * Used to retry SESSION_END delivery after a (re)connect so pruning can eventually
	 * catch up on sessions that were finalized while offline.
	 */
	public List<SplashSession> getUnsyncedSessions()
	{
		List<SplashSession> unsynced = new ArrayList<>();
		for (SplashSession session : sessionHistory)
		{
			// Exclude a session still sitting in its resume window: it hasn't been reported
			// to the backend as ended yet on purpose (it may still be resumed), so a
			// reconnect happening mid-window must not prematurely notify it as finalized.
			if (!session.isSynced() && session != resumableSession)
			{
				unsynced.add(session);
			}
		}
		return unsynced;
	}

	/**
	 * Delete a specific session from history.
	 */
	public void deleteSession(SplashSession session)
	{
		if (session != null && sessionHistory.remove(session))
		{
			saveSessionHistory();
			log.debug("Deleted session from history: {}", session.getPlayerName());
		}
	}

	/**
	 * Export all session history as a JSON string for REST API upload.
	 * @return JSON string of all persisted sessions
	 */
	public String exportSessionsAsJson()
	{
		List<PersistedSession> persistedSessions = new ArrayList<>();
		for (SplashSession session : sessionHistory)
		{
			persistedSessions.add(PersistedSession.fromSession(session));
		}

		// Include active session if present
		if (currentSession != null && currentSession.isActive())
		{
			persistedSessions.add(PersistedSession.fromSession(currentSession));
		}

		return gson.toJson(persistedSessions);
	}

	/**
	 * Export all session history to a file.
	 * @param file The file to write to
	 * @throws java.io.IOException if writing fails
	 */
	public void exportSessionsToFile(java.io.File file) throws java.io.IOException
	{
		String json = exportSessionsAsJson();
		try (java.io.FileWriter writer = new java.io.FileWriter(file))
		{
			writer.write(json);
		}
		log.debug("Exported {} sessions to {}", sessionHistory.size(), file.getAbsolutePath());
	}

	/**
	 * Custom serializer for Instant to avoid Java module access issues.
	 */
	private static class InstantSerializer implements JsonSerializer<Instant>
	{
		@Override
		public JsonElement serialize(Instant src, java.lang.reflect.Type typeOfSrc, JsonSerializationContext context)
		{
			return new JsonPrimitive(src.toString());
		}
	}

	/**
	 * Custom deserializer for Instant to avoid Java module access issues.
	 */
	private static class InstantDeserializer implements JsonDeserializer<Instant>
	{
		@Override
		public Instant deserialize(JsonElement json, java.lang.reflect.Type typeOfT, JsonDeserializationContext context)
		{
			return Instant.parse(json.getAsString());
		}
	}

}

package xyz.peppie.splashhelper.service;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.config.ConfigManager;
import xyz.peppie.splashhelper.SplashHelperConfig;
import xyz.peppie.splashhelper.util.Constants;
import net.runelite.api.coords.WorldPoint;

import java.time.Instant;

/**
 * Service for managing tile-related functionality including boundary tiles, knight tiles, and movement tracking.
 */
@Slf4j
@Singleton
public class TileManager
{
	private static final String CONFIG_GROUP = "splashhelper";
	private static final String CONFIG_BOUNDARY_TILE = "boundaryTile";
	private static final String CONFIG_KNIGHT_TILE1 = "knightTile1";
	private static final String CONFIG_KNIGHT_TILE2 = "knightTile2";

	@Inject
	private SplashHelperConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SessionManager sessionManager;

	@Inject
	private NotificationService notificationService;

	@Getter
	private WorldPoint boundaryTile = null;

	@Getter
	private WorldPoint knightTile1 = null;

	@Getter
	private WorldPoint knightTile2 = null;

	// Movement tracking
	private WorldPoint lastNpcPosition = null;
	private int movementCount = 0;
	private Instant trackingStartTime = null;
	@Getter
	private double movementsPerHour = 0.0;

	// hasEscaped state machine
	@Getter
	private boolean hasEscaped = false;
	private int boundaryTickCounter = 0;
	private boolean boundaryNotified = false;

	// Current target
	@Getter
	private Actor currentTarget = null;

	// The exact knight NPC this splashing session was started on. Captured the
	// first time a target is engaged and held until the target is cleared, so
	// safety mode can restrict clicks to this knight only (and not a second
	// knight dragged in by a griefer).
	@Getter
	private NPC sessionKnight = null;

	/**
	 * Set the boundary tile.
	 */
	public void setBoundaryTile(WorldPoint tile)
	{
		this.boundaryTile = tile;
		boundaryNotified = false;
		saveTile(CONFIG_BOUNDARY_TILE, tile);
		log.debug("✓ Boundary tile successfully set to: {}", tile);
	}

	/**
	 * Unset the boundary tile.
	 */
	public void unsetBoundaryTile()
	{
		boundaryTile = null;
		boundaryNotified = false;
		saveTile(CONFIG_BOUNDARY_TILE, null);
		log.debug("✓ Boundary tile unset");
	}

	/**
	 * Set knight tile 1.
	 */
	public void setKnightTile1(WorldPoint tile)
	{
		this.knightTile1 = tile;
		saveTile(CONFIG_KNIGHT_TILE1, tile);
		log.debug("✓ Knight Tile 1 successfully set to: {}", tile);

		// Initialize tracking if both tiles are set
		if (knightTile1 != null && knightTile2 != null)
		{
			resetMovementTracking();
		}
	}

	/**
	 * Unset knight tile 1.
	 */
	public void unsetKnightTile1()
	{
		knightTile1 = null;
		saveTile(CONFIG_KNIGHT_TILE1, null);
		resetMovementTracking();
		log.debug("✓ Knight Tile 1 unset");
	}

	/**
	 * Set knight tile 2.
	 */
	public void setKnightTile2(WorldPoint tile)
	{
		this.knightTile2 = tile;
		saveTile(CONFIG_KNIGHT_TILE2, tile);
		log.debug("✓ Knight Tile 2 successfully set to: {}", tile);

		// Initialize tracking if both tiles are set
		if (knightTile1 != null && knightTile2 != null)
		{
			resetMovementTracking();
		}
	}

	/**
	 * Unset knight tile 2.
	 */
	public void unsetKnightTile2()
	{
		knightTile2 = null;
		saveTile(CONFIG_KNIGHT_TILE2, null);
		resetMovementTracking();
		log.debug("✓ Knight Tile 2 unset");
	}

	/**
	 * Set the current target.
	 */
	public void setCurrentTarget(Actor target)
	{
		if (target == null)
		{
			// Target cleared (knight died / session reset) releases the lock so a
			// fresh session can lock onto whichever knight it starts on.
			sessionKnight = null;
		}
		else if (sessionKnight == null && target instanceof NPC)
		{
			// Lock onto the first knight this session engages with.
			sessionKnight = (NPC) target;
		}
		this.currentTarget = target;
	}

	/**
	 * Reset movement tracking.
	 */
	public void resetMovementTracking()
	{
		lastNpcPosition = null;
		movementCount = 0;
		trackingStartTime = null;
		movementsPerHour = 0.0;
	}

	/**
	 * Track NPC movement between Knight Tile 1 and Knight Tile 2.
	 */
	public void trackKnightMovement()
	{
		if (knightTile1 != null && knightTile2 != null && currentTarget != null)
		{
			WorldPoint currentPosition = currentTarget.getWorldLocation();

			if (currentPosition != null)
			{
				// Check if NPC is on either Knight Tile
				boolean onTile1 = currentPosition.equals(knightTile1);
				boolean onTile2 = currentPosition.equals(knightTile2);

				if (onTile1 || onTile2)
				{
					// Initialize tracking on first detection
					if (trackingStartTime == null)
					{
						trackingStartTime = Instant.now();
						lastNpcPosition = currentPosition;
					}
					// Check if NPC moved between tiles
					else if (lastNpcPosition != null && !currentPosition.equals(lastNpcPosition))
					{
						// Only count movements between the two tiles
						boolean wasOnTile1 = lastNpcPosition.equals(knightTile1);
						boolean wasOnTile2 = lastNpcPosition.equals(knightTile2);

						if ((wasOnTile1 && onTile2) || (wasOnTile2 && onTile1))
						{
							movementCount++;
							sessionManager.recordKnightMovement();
						}

						lastNpcPosition = currentPosition;
					}

					// Calculate movements per hour
					if (trackingStartTime != null)
					{
						java.time.Duration trackingDuration = java.time.Duration.between(trackingStartTime, Instant.now());
						double hours = trackingDuration.toMillis() / 3_600_000.0;

						if (hours > 0)
						{
							movementsPerHour = movementCount / hours;
						}
					}
				}
			}
		}
	}

	/**
	 * Update knight position tracking and boundary notifications.
	 * Returns true if boundary notification should be sent.
	 */
	public boolean updateKnightPositionTracking()
	{
		boolean shouldNotifyBoundary = false;

		if (currentTarget != null && currentTarget instanceof NPC)
		{
			NPC knight = (NPC) currentTarget;
			WorldPoint knightPos = knight.getWorldLocation();

			if (knightPos != null)
			{
				boolean onKnightTile = (knightTile1 != null && knightPos.equals(knightTile1)) ||
									   (knightTile2 != null && knightPos.equals(knightTile2));
				boolean onBoundary = boundaryTile != null && knightPos.equals(boundaryTile);

				// hasEscaped state machine
				if (onBoundary)
				{
					if (!hasEscaped)
					{
						hasEscaped = true;
						boundaryTickCounter = 0;

						// Send notification only once when entering boundary
						if (!boundaryNotified && config.enableBoundaryNotification())
						{
							shouldNotifyBoundary = true;
							boundaryNotified = true;
						}
					}
					else
					{
						boundaryTickCounter++;
					}
				}
				else if (onKnightTile)
				{
					// Knight returned to original tile
					if (hasEscaped)
					{
						hasEscaped = false;
						boundaryNotified = false;
						boundaryTickCounter = 0;
						notificationService.unmuteNotifications();
					}
				}
				else
				{
					// Knight is on some other tile (not boundary, not knight tiles)
					if (hasEscaped)
					{
						boundaryTickCounter++;
						// After 5 ticks on a non-valid tile, allow re-notification
						if (boundaryTickCounter >= Constants.BOUNDARY_DEBOUNCE_TICKS)
						{
							boundaryNotified = false;
						}
					}
				}
			}
		}

		return shouldNotifyBoundary;
	}

	/**
	 * Reset the hasEscaped state.
	 */
	public void resetEscapedState()
	{
		hasEscaped = false;
		boundaryNotified = false;
		boundaryTickCounter = 0;
		notificationService.unmuteNotifications();
	}

	/**
	 * Reset all tile and tracking state.
	 */
	public void reset()
	{
		// Keep persisted tiles (boundaryTile, knightTile1, knightTile2) — they are restored on startup
		currentTarget = null;
		sessionKnight = null;
		boundaryNotified = false;
		lastNpcPosition = null;
		movementCount = 0;
		trackingStartTime = null;
		movementsPerHour = 0.0;
		hasEscaped = false;
		boundaryTickCounter = 0;
		notificationService.unmuteNotifications();
	}

	/**
	 * Load persisted tiles from config. Called on plugin startup.
	 */
	public void loadPersistedTiles()
	{
		boundaryTile = loadTile(CONFIG_BOUNDARY_TILE);
		knightTile1 = loadTile(CONFIG_KNIGHT_TILE1);
		knightTile2 = loadTile(CONFIG_KNIGHT_TILE2);
		log.debug("Loaded persisted tiles - boundary: {}, knight1: {}, knight2: {}", boundaryTile, knightTile1, knightTile2);
	}

	private void saveTile(String key, WorldPoint tile)
	{
		if (tile == null)
		{
			configManager.unsetConfiguration(CONFIG_GROUP, key);
		}
		else
		{
			String value = tile.getX() + "," + tile.getY() + "," + tile.getPlane();
			configManager.setConfiguration(CONFIG_GROUP, key, value);
		}
	}

	private WorldPoint loadTile(String key)
	{
		String value = configManager.getConfiguration(CONFIG_GROUP, key);
		if (value == null || value.isEmpty())
		{
			return null;
		}
		try
		{
			String[] parts = value.split(",");
			return new WorldPoint(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
		}
		catch (Exception e)
		{
			log.warn("Failed to parse persisted tile '{}': {}", key, e.getMessage());
			return null;
		}
	}
}

package xyz.peppie.splashhelper.service;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import xyz.peppie.splashhelper.util.Constants;

/**
 * Service responsible for detecting and analyzing the Knight of Ardougne NPC.
 * Handles sticky knight detection based on NPC IDs.
 */
@Singleton
public class KnightDetector
{
	@Inject
	public KnightDetector()
	{
	}

	/**
	 * Check if the given actor is a "sticky" knight (female variant).
	 * Sticky knights have a smaller clickbox and are preferred for splashing.
	 * Detection is based on NPC ID.
	 */
	public boolean isStickyKnight(Actor target)
	{
		if (target == null || !(target instanceof NPC))
		{
			return false;
		}

		NPC knight = (NPC) target;
		int npcId = knight.getId();

		return npcId == Constants.FEMALE_KNIGHT_NPC_ID;
	}
}

package xyz.peppie.splashhelper.service;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import xyz.peppie.splashhelper.model.SplashSpell;
import xyz.peppie.splashhelper.util.Constants;

/**
 * Service responsible for all rune-related calculations including:
 * - Counting runes in inventory and rune pouch
 * - Detecting combination runes
 * - Detecting infinite runes from equipped staves
 * - Calculating remaining spell casts
 */
@Singleton
public class RuneCalculator
{
	private final Client client;

	@Inject
	public RuneCalculator(Client client)
	{
		this.client = client;
	}

	/**
	 * Calculate remaining casts for a spell, accounting for combo runes, pouch, and staves.
	 */
	public int getRemainingCasts(SplashSpell spell)
	{
		if (spell == null)
		{
			return 0;
		}

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return 0;
		}

		Set<Integer> infiniteRunes = getInfiniteRunesFromEquipment();
		Map<Integer, Integer> runeCounts = buildRuneCountMap(inventory);

		int minCasts = Integer.MAX_VALUE;

		for (SplashSpell.RuneCost cost : spell.getRuneCosts())
		{
			if (infiniteRunes.contains(cost.getItemId()))
			{
				continue;
			}

			int runeCount = runeCounts.getOrDefault(cost.getItemId(), 0);
			int castsWithThisRune = runeCount / cost.getAmount();
			minCasts = Math.min(minCasts, castsWithThisRune);
		}

		return minCasts == Integer.MAX_VALUE ? 0 : minCasts;
	}

	/**
	 * Get the actual runes being consumed for a spell.
	 * Detects combination runes in inventory and excludes infinite runes from staves.
	 * @return List of int[2] arrays: [itemId, amountPerCast]
	 */
	public List<int[]> getActualRuneUsage(SplashSpell spell)
	{
		List<int[]> result = new ArrayList<>();

		if (spell == null)
		{
			return result;
		}

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return result;
		}

		Set<Integer> infiniteRunes = getInfiniteRunesFromEquipment();
		Map<Integer, Integer> comboRunesInInventory = findCombinationRunes(inventory);

		for (SplashSpell.RuneCost cost : spell.getRuneCosts())
		{
			int requiredRuneId = cost.getItemId();

			if (infiniteRunes.contains(requiredRuneId))
			{
				continue;
			}

			int comboRuneId = findCombinationRuneFor(requiredRuneId, comboRunesInInventory.keySet());
			if (comboRuneId > 0)
			{
				result.add(new int[]{comboRuneId, cost.getAmount()});
			}
			else
			{
				result.add(new int[]{requiredRuneId, cost.getAmount()});
			}
		}

		return deduplicateRuneUsage(result);
	}

	/**
	 * Get set of rune IDs that are provided infinitely by equipped staves.
	 */
	public Set<Integer> getInfiniteRunesFromEquipment()
	{
		Set<Integer> infiniteRunes = new HashSet<>();

		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return infiniteRunes;
		}

		for (Item item : equipment.getItems())
		{
			int id = item.getId();

			// Air staves
			if (id == Constants.STAFF_OF_AIR || id == Constants.AIR_BATTLESTAFF || id == Constants.MYSTIC_AIR_STAFF ||
				id == Constants.SMOKE_BATTLESTAFF || id == Constants.MYSTIC_SMOKE_STAFF ||
				id == Constants.DUST_BATTLESTAFF || id == Constants.MYSTIC_DUST_STAFF ||
				id == Constants.MIST_BATTLESTAFF || id == Constants.MYSTIC_MIST_STAFF)
			{
				infiniteRunes.add(Constants.AIR_RUNE);
			}

			// Water staves
			if (id == Constants.STAFF_OF_WATER || id == Constants.WATER_BATTLESTAFF || id == Constants.MYSTIC_WATER_STAFF ||
				id == Constants.STEAM_BATTLESTAFF || id == Constants.MYSTIC_STEAM_STAFF ||
				id == Constants.MIST_BATTLESTAFF || id == Constants.MYSTIC_MIST_STAFF ||
				id == Constants.MUD_BATTLESTAFF || id == Constants.MYSTIC_MUD_STAFF)
			{
				infiniteRunes.add(Constants.WATER_RUNE);
			}

			// Earth staves
			if (id == Constants.STAFF_OF_EARTH || id == Constants.EARTH_BATTLESTAFF || id == Constants.MYSTIC_EARTH_STAFF ||
				id == Constants.DUST_BATTLESTAFF || id == Constants.MYSTIC_DUST_STAFF ||
				id == Constants.MUD_BATTLESTAFF || id == Constants.MYSTIC_MUD_STAFF ||
				id == Constants.LAVA_BATTLESTAFF || id == Constants.MYSTIC_LAVA_STAFF)
			{
				infiniteRunes.add(Constants.EARTH_RUNE);
			}

			// Fire staves
			if (id == Constants.STAFF_OF_FIRE || id == Constants.FIRE_BATTLESTAFF || id == Constants.MYSTIC_FIRE_STAFF ||
				id == Constants.SMOKE_BATTLESTAFF || id == Constants.MYSTIC_SMOKE_STAFF ||
				id == Constants.STEAM_BATTLESTAFF || id == Constants.MYSTIC_STEAM_STAFF ||
				id == Constants.LAVA_BATTLESTAFF || id == Constants.MYSTIC_LAVA_STAFF)
			{
				infiniteRunes.add(Constants.FIRE_RUNE);
			}
		}

		return infiniteRunes;
	}

	/**
	 * Build a map of rune type -> count (including combo runes and pouch).
	 */
	private Map<Integer, Integer> buildRuneCountMap(ItemContainer inventory)
	{
		Map<Integer, Integer> runeCounts = new HashMap<>();

		for (Item item : inventory.getItems())
		{
			int id = item.getId();
			int qty = item.getQuantity();

			if (Constants.isBasicRune(id))
			{
				runeCounts.merge(id, qty, (existing, newValue) -> existing == null ? newValue : existing + newValue);
			}

			addCombinationRuneCounts(runeCounts, id, qty);

			if (id == Constants.RUNE_POUCH || id == Constants.RUNE_POUCH_DIVINE)
			{
				addRunePouchCounts(runeCounts);
			}
		}

		return runeCounts;
	}

	/**
	 * Find combination runes in inventory and rune pouch.
	 */
	private Map<Integer, Integer> findCombinationRunes(ItemContainer inventory)
	{
		Map<Integer, Integer> comboRunes = new HashMap<>();

		for (Item item : inventory.getItems())
		{
			int id = item.getId();
			if (Constants.isCombinationRune(id))
			{
				comboRunes.put(id, item.getQuantity());
			}
		}

		// Check rune pouch for combo runes
		for (int i = 0; i < 3; i++)
		{
			int runeId = runeIdFromVarbit(client.getVarbitValue(Constants.RUNE_POUCH_RUNE_VARBITS[i]));
			int amount = client.getVarbitValue(Constants.RUNE_POUCH_AMOUNT_VARBITS[i]);
			if (runeId > 0 && amount > 0 && Constants.isCombinationRune(runeId))
			{
				comboRunes.merge(runeId, amount, (existing, newValue) -> existing == null ? newValue : existing + newValue);
			}
		}

		return comboRunes;
	}

	/**
	 * Add combination rune counts to the rune map (both element types).
	 */
	private void addCombinationRuneCounts(Map<Integer, Integer> runeCounts, int itemId, int quantity)
	{
		switch (itemId)
		{
			case Constants.MIST_RUNE:
				runeCounts.merge(
					Constants.AIR_RUNE, quantity,
					(existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				runeCounts.merge(
					Constants.WATER_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				break;
			case Constants.DUST_RUNE:
				runeCounts.merge(
					Constants.AIR_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				runeCounts.merge(
					Constants.EARTH_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				break;
			case Constants.MUD_RUNE:
				runeCounts.merge(
					Constants.WATER_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				runeCounts.merge(
					Constants.EARTH_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				break;
			case Constants.SMOKE_RUNE:
				runeCounts.merge(
					Constants.AIR_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				runeCounts.merge(
					Constants.FIRE_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				break;
			case Constants.STEAM_RUNE:
				runeCounts.merge(
					Constants.WATER_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				runeCounts.merge(
					Constants.FIRE_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				break;
			case Constants.LAVA_RUNE:
				runeCounts.merge(
					Constants.EARTH_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				runeCounts.merge(
					Constants.FIRE_RUNE,
					quantity, (existing, newValue) -> existing == null ? newValue : existing + newValue
				);
				break;
		}
	}

	/**
	 * Add rune counts from rune pouch to the map.
	 */
	private void addRunePouchCounts(Map<Integer, Integer> runeCounts)
	{
		for (int i = 0; i < 3; i++)
		{
			int runeId = runeIdFromVarbit(client.getVarbitValue(Constants.RUNE_POUCH_RUNE_VARBITS[i]));
			int amount = client.getVarbitValue(Constants.RUNE_POUCH_AMOUNT_VARBITS[i]);

			if (runeId > 0 && amount > 0)
			{
				runeCounts.merge(runeId, amount, (existing, newValue) -> existing == null ? newValue : existing + newValue);
				addCombinationRuneCounts(runeCounts, runeId, amount);
			}
		}
	}

	/**
	 * Convert varbit value to rune item ID.
	 */
	private int runeIdFromVarbit(int varbitValue)
	{
		switch (varbitValue)
		{
			case 1: return Constants.AIR_RUNE;
			case 2: return Constants.WATER_RUNE;
			case 3: return Constants.EARTH_RUNE;
			case 4: return Constants.FIRE_RUNE;
			case 5: return Constants.MIND_RUNE;
			case 6: return Constants.BODY_RUNE;
			case 7: return Constants.DEATH_RUNE;
			case 8: return 561; // Nature rune
			case 9: return Constants.CHAOS_RUNE;
			case 10: return 563; // Law rune
			case 11: return 564; // Cosmic rune
			case 12: return Constants.BLOOD_RUNE;
			case 13: return 566; // Soul rune
			case 14: return 9075; // Astral rune
			case 15: return Constants.MIST_RUNE;
			case 16: return Constants.MUD_RUNE;
			case 17: return Constants.DUST_RUNE;
			case 18: return Constants.LAVA_RUNE;
			case 19: return Constants.STEAM_RUNE;
			case 20: return Constants.SMOKE_RUNE;
			case 21: return Constants.WRATH_RUNE;
			default: return -1;
		}
	}

	/**
	 * Find a combination rune that provides the required element.
	 */
	private int findCombinationRuneFor(int elementRuneId, Set<Integer> availableComboRunes)
	{
		for (int comboId : availableComboRunes)
		{
			if (combinationRuneProvides(comboId, elementRuneId))
			{
				return comboId;
			}
		}
		return -1;
	}

	/**
	 * Check if a combination rune provides a specific element.
	 */
	private boolean combinationRuneProvides(int comboRuneId, int elementRuneId)
	{
		switch (comboRuneId)
		{
			case Constants.MIST_RUNE:
				return elementRuneId == Constants.AIR_RUNE || elementRuneId == Constants.WATER_RUNE;
			case Constants.DUST_RUNE:
				return elementRuneId == Constants.AIR_RUNE || elementRuneId == Constants.EARTH_RUNE;
			case Constants.MUD_RUNE:
				return elementRuneId == Constants.WATER_RUNE || elementRuneId == Constants.EARTH_RUNE;
			case Constants.SMOKE_RUNE:
				return elementRuneId == Constants.AIR_RUNE || elementRuneId == Constants.FIRE_RUNE;
			case Constants.STEAM_RUNE:
				return elementRuneId == Constants.WATER_RUNE || elementRuneId == Constants.FIRE_RUNE;
			case Constants.LAVA_RUNE:
				return elementRuneId == Constants.EARTH_RUNE || elementRuneId == Constants.FIRE_RUNE;
			default:
				return false;
		}
	}

	/**
	 * Deduplicate rune usage list (combo runes providing multiple elements).
	 */
	private List<int[]> deduplicateRuneUsage(List<int[]> runeUsage)
	{
		Map<Integer, Integer> seen = new LinkedHashMap<>();
		for (int[] entry : runeUsage)
		{
			int itemId = entry[0];
			int amount = entry[1];
			if (!seen.containsKey(itemId))
			{
				seen.put(itemId, amount);
			}
		}

		List<int[]> result = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : seen.entrySet())
		{
			result.add(new int[]{entry.getKey(), entry.getValue()});
		}
		return result;
	}
}

package xyz.peppie.splashhelper.service;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.Base64;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;
import xyz.peppie.splashhelper.SplashHelperConfig;
import xyz.peppie.splashhelper.model.PlayerCountSeries;
import xyz.peppie.splashhelper.model.SplashSession;

/**
 * Manages a persistent WebSocket connection to the Splash Helper server.
 * Handles authentication, session lifecycle messaging, and automatic reconnection.
 */
@Slf4j
@Singleton
public class SplashWebSocketClient
{
	private final SplashHelperConfig config;
	private final ConfigManager configManager;
	private final Gson gson;
	private final Client client;
	private final ClientThread clientThread;
	private final OkHttpClient okHttpClient;
	private volatile ScheduledExecutorService executor;

	private volatile WebSocket webSocket;
	private final AtomicBoolean connected = new AtomicBoolean(false);
	private final AtomicBoolean authenticated = new AtomicBoolean(false);
	private final AtomicBoolean connecting = new AtomicBoolean(false);
	private final AtomicBoolean reconnectScheduled = new AtomicBoolean(false);
	private volatile boolean intentionalDisconnect = false;
	private volatile String activeUsername;
	private int reconnectAttempts = 0;

	/** Minimum milliseconds between SESSION_UPDATE messages sent to the server. */
	private static final long UPDATE_THROTTLE_MS = 10_000L;
	private volatile long lastUpdateSentMs = 0;

	/** The most recently received setup link URL, or null if none. */
	@Getter
	private volatile String setupLink;

	/** Epoch-second expiry of the current setup link JWT, or 0 if unknown. */
	private volatile long setupLinkExpiry;

	/** True once we have logged the setup-required message for the current connection. Cleared on each new open. */
	private volatile boolean setupLinkLoggedThisConnection = false;

	/** Called once whenever AUTH_SUCCESS is received (initial auth or re-auth). */
	private volatile Runnable onAuthSuccessCallback;

	public void setOnAuthSuccessCallback(Runnable callback)
	{
		this.onAuthSuccessCallback = callback;
	}

	/** A SESSION_START that arrived before authentication completed; sent once auth succeeds. */
	private volatile SplashSession pendingSessionStart = null;

	/** Returns true if the WebSocket is currently connected. */
	public boolean isConnected()
	{
		return connected.get();
	}

	/** Returns true if the WebSocket is connected and authenticated. */
	public boolean isAuthenticated()
	{
		return authenticated.get();
	}

	/**
	 * Tracks the result of the most recent AUTH_SUCCESS:
	 * null = no auth response yet, true = account needs setup, false = already set up.
	 */
	@Getter
	private volatile Boolean lastAuthSetupRequired = null;

	private static final String TOKEN_CONFIG_KEY = "playerToken";
	private static final String CONFIG_GROUP = "splashhelper";
	private static final int[] RECONNECT_DELAYS_SECONDS = {2, 4, 8, 16, 30};
	private static final int WS_NORMAL_CLOSURE = 1000;

	@Inject
	public SplashWebSocketClient(SplashHelperConfig config, ConfigManager configManager,
								 Gson gson, Client client, ClientThread clientThread, OkHttpClient okHttpClient)
	{
		this.config = config;
		this.configManager = configManager;
		this.gson = gson;
		this.client = client;
		this.clientThread = clientThread;
		this.okHttpClient = okHttpClient;
	}

	/**
	 * Returns the executor, creating a new one if necessary (e.g. after a previous shutdown).
	 * The singleton survives plugin disable/enable cycles so the executor must be recreatable.
	 */
	private synchronized ScheduledExecutorService executor()
	{
		if (executor == null || executor.isShutdown())
		{
			executor = Executors.newSingleThreadScheduledExecutor(r -> {
				Thread t = new Thread(r, "splash-helper-ws");
				t.setDaemon(true);
				return t;
			});
		}
		return executor;
	}

	/**
	 * Connect to the configured WebSocket server as the given username.
	 * No-op if server sync is disabled in config.
	 */
	public void connect(String username)
	{
		if (!config.enableServerSync())
		{
			return;
		}
		if (username == null || username.trim().isEmpty())
		{
			return;
		}

		String trimmedUsername = username.trim();
		if (trimmedUsername.equals(activeUsername) && (connected.get() || connecting.get()))
		{
			return;
		}

		authenticated.set(false);
		this.activeUsername = trimmedUsername;
		this.intentionalDisconnect = false;
		reconnectScheduled.set(false);
		// Set connecting BEFORE submitting to the executor so that a second connect()
		// call arriving before doConnect() runs is blocked by the guard above.
		connecting.set(true);
		executor().execute(this::doConnect);
	}

	/**
	 * Disconnect from the server and cancel any pending reconnects.
	 * The actual WS close is submitted to the executor so any already-queued
	 * messages (e.g. SESSION_END) are sent before the connection is torn down.
	 */
	public void disconnect()
	{
		intentionalDisconnect = true;
		authenticated.set(false);
		connecting.set(false);
		reconnectScheduled.set(false);
		// Submit the real close to the executor so it runs *after* any pending
		// SESSION_END (or other) messages that were already queued before this call.
		ScheduledExecutorService ex = this.executor;
		if (ex != null && !ex.isShutdown())
		{
			ex.execute(this::doDisconnect);
		}
		else
		{
			doDisconnect();
		}
	}

	private void doDisconnect()
	{
		WebSocket ws = this.webSocket;
		connecting.set(false);
		pendingSessionStart = null;
		if (ws != null && connected.getAndSet(false))
		{
			try
			{
				ws.close(WS_NORMAL_CLOSURE, "plugin shutdown");
			}
			catch (Exception e)
			{
				log.debug("WS close error: {}", e.getMessage());
			}
		}
		webSocket = null;
	}

	/**
	 * Clears the persisted player token and reconnects, causing a brand-new token (and
	 * therefore a fresh server-side account link) to be generated. Use this to recover
	 * when the stored token is bound to a different account — e.g. after switching which
	 * OSRS account plays through this RuneLite client — which otherwise causes every
	 * connection attempt to fail authentication with the old, mismatched token.
	 */
	public void resetToken()
	{
		String username = activeUsername;
		reconnectScheduled.set(false);
		reconnectAttempts = 0;
		pendingSessionStart = null;
		setupLink = null;
		setupLinkExpiry = 0;
		lastAuthSetupRequired = null;

		// Tear down any existing connection and drop the stored token on the executor
		// thread, so a reconnect queued right after this is guaranteed to run after the
		// token has actually been cleared (single-threaded executor preserves order).
		executor().execute(() -> {
			doDisconnect();
			if (username != null)
			{
				configManager.unsetConfiguration(CONFIG_GROUP, tokenConfigKey(username));
			}
			log.info("Player token reset; a new one will be generated on next connect");
		});

		if (username != null)
		{
			// Force connect() past its "already connected/connecting as this user" guard,
			// since activeUsername hasn't changed but the underlying token has.
			activeUsername = null;
			connect(username);
		}
	}

	/**
	 * Returns the currently stored sync token for the active account, or null if none has
	 * been generated yet. Non-destructive — unlike {@link #resetToken()}, this does not
	 * clear or regenerate it.
	 */
	public String getCurrentToken()
	{
		String username = activeUsername;
		if (username == null)
		{
			return null;
		}
		String token = configManager.getConfiguration(CONFIG_GROUP, tokenConfigKey(username));
		if (token == null || token.trim().isEmpty())
		{
			// Not yet migrated to the per-account key (e.g. no connection attempt has run
			// since upgrading) — fall back to the legacy shared token so Copy Token still
			// works before the first reconnect performs the migration.
			token = configManager.getConfiguration(CONFIG_GROUP, TOKEN_CONFIG_KEY);
		}
		return token;
	}

	/**
	 * Returns true if a setup link has been received and its JWT has not expired.
	 */
	public boolean isSetupLinkValid()
	{
		if (setupLink == null)
		{
			return false;
		}
		if (setupLinkExpiry <= 0)
		{
			return true; // could not parse expiry — assume valid
		}
		return Instant.now().getEpochSecond() < setupLinkExpiry;
	}

	/**
	 * Re-authenticates with the server to request a fresh setup link.
	 * If not connected, attempts to connect first (auth happens on connect).
	 */
	public void requestSetupLink()
	{
		lastAuthSetupRequired = null; // reset so caller can detect a fresh response
		if (connected.get())
		{
			executor().execute(this::sendAuth);
		}
		else if (activeUsername != null)
		{
			intentionalDisconnect = false;
			executor().execute(this::doConnect);
		}
	}

	/** Send a SESSION_START message for the given session. */
	public void sendSessionStart(SplashSession session)
	{
		if (session == null)
		{
			return;
		}
		if (!authenticated.get())
		{
			// Not authenticated yet — queue so it is sent as soon as AUTH_SUCCESS arrives
			if (!intentionalDisconnect)
			{
				pendingSessionStart = session;
			}
			return;
		}
		pendingSessionStart = null;
		executor().execute(() -> {
			JsonObject msg = new JsonObject();
			msg.addProperty("type", "SESSION_START");
			msg.add("sessionData", buildSessionData(session));
			sendJson(msg);
		});
	}

	/**
	 * Send a SESSION_UPDATE message, throttled to at most once every
	 * {@link #UPDATE_THROTTLE_MS} milliseconds.
	 */
	public void sendSessionUpdate(SplashSession session)
	{
		if (!authenticated.get() || session == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (now - lastUpdateSentMs < UPDATE_THROTTLE_MS)
		{
			return;
		}
		lastUpdateSentMs = now;
		executor().execute(() -> {
			JsonObject msg = new JsonObject();
			msg.addProperty("type", "SESSION_UPDATE");
			msg.add("sessionData", buildSessionData(session));
			sendJson(msg);
		});
	}

	/**
	 * Send a SESSION_END message for the given finalized session.
	 * On successful handoff to the socket, marks the session as synced so local pruning
	 * (see SessionManager) knows it is now safe to delete once it ages out of retention.
	 */
	public void sendSessionEnd(SplashSession session)
	{
		// Check connected (not authenticated) — disconnect() clears authenticated before
		// the executor runs, so SESSION_END would be silently dropped otherwise.
		if (!connected.get() || session == null)
		{
			return;
		}
		executor().execute(() -> {
			WebSocket ws = webSocket;
			if (ws == null || !connected.get())
			{
				return;
			}
			JsonObject msg = new JsonObject();
			msg.addProperty("type", "SESSION_END");
			msg.add("sessionData", buildSessionData(session));
			if (ws.send(gson.toJson(msg)))
			{
				session.setSynced(true);
			}
			else
			{
				log.warn("WS send failed: message not enqueued");
			}
		});
	}

	/**
	 * Re-send SESSION_END for any previously finalized sessions that haven't been
	 * confirmed synced yet (e.g. they were finalized while disconnected). Called after a
	 * successful (re)authentication so pruning can eventually catch up on them.
	 */
	public void resyncUnsyncedSessions(java.util.List<SplashSession> unsyncedSessions)
	{
		if (unsyncedSessions == null)
		{
			return;
		}
		for (SplashSession session : unsyncedSessions)
		{
			if (session != null && !session.isSynced())
			{
				sendSessionEnd(session);
			}
		}
	}

	// ==================== Internal helpers ====================

	private void doConnect()
	{
		if (intentionalDisconnect)
		{
			connecting.set(false);
			return;
		}

		// connecting is already set to true by connect() or scheduleReconnect().
		// Guard against any path that skipped that (shouldn't happen, but be safe).
		connecting.set(true);

		// If an old WebSocket is still open (e.g. world hop), close it cleanly first
		if (connected.get() && webSocket != null)
		{
			try
			{
				webSocket.close(WS_NORMAL_CLOSURE, "reconnecting");
			}
			catch (Exception e)
			{
				log.debug("WS close before reconnect: {}", e.getMessage());
			}
			connected.set(false);
			authenticated.set(false);
			webSocket = null;
		}
		String rawUrl = config.serverUrl();
		String url = (rawUrl == null || rawUrl.trim().isEmpty()) ? "ws://localhost:3000" : rawUrl.trim();

		try
		{
			Request request = new Request.Builder().url(url).build();
			webSocket = okHttpClient.newWebSocket(request, new WsListener());
		}
		catch (Exception e)
		{
			connecting.set(false);
			log.warn("WS connect error: {}", e.getMessage());
			if (!intentionalDisconnect)
			{
				scheduleReconnect();
			}
		}
	}

	private void scheduleReconnect()
	{
		if (intentionalDisconnect || connected.get() || connecting.get())
		{
			return;
		}
		if (!reconnectScheduled.compareAndSet(false, true))
		{
			return;
		}

		// Mirror connect(): set the flag before the task runs to block concurrent races.
		connecting.set(true);
		int delayIdx = Math.min(reconnectAttempts, RECONNECT_DELAYS_SECONDS.length - 1);
		int delaySeconds = RECONNECT_DELAYS_SECONDS[delayIdx];
		reconnectAttempts++;
		log.debug("WS reconnect in {}s (attempt {})", delaySeconds, reconnectAttempts);
		executor().schedule(() -> {
			reconnectScheduled.set(false);
			doConnect();
		}, delaySeconds, TimeUnit.SECONDS);
	}

	private void sendAuth()
	{
		String username = activeUsername;
		String token = getOrCreateToken(username);
		JsonObject msg = new JsonObject();
		msg.addProperty("type", "AUTH");
		msg.addProperty("username", username != null ? username : "");
		msg.addProperty("token", token);
		sendJson(msg);
	}

	private void sendJson(JsonObject msg)
	{
		WebSocket ws = this.webSocket;
		if (ws == null || !connected.get())
		{
			return;
		}
		String json = gson.toJson(msg);
		if (!ws.send(json))
		{
			log.warn("WS send failed: message not enqueued");
		}
	}

	private void handleMessage(String text)
	{
		try
		{
			JsonObject msg = gson.fromJson(text, JsonObject.class);
			if (msg == null || !msg.has("type"))
			{
				return;
			}
			String type = msg.get("type").getAsString();
			switch (type)
			{
				case "AUTH_SUCCESS":
					authenticated.set(true);
					reconnectScheduled.set(false);
					reconnectAttempts = 0;
					boolean setupRequired = msg.has("setupRequired") && msg.get("setupRequired").getAsBoolean();
					lastAuthSetupRequired = setupRequired;
					if (setupRequired && msg.has("setupLink"))
					{
						String link = msg.get("setupLink").getAsString();
						setupLink = link;
						setupLinkExpiry = parseJwtExpiry(link);
						// Only log once per connection to avoid spamming the console on reconnects
						// (each reconnect generates a new JWT so link-equality checks don't help).
						if (!setupLinkLoggedThisConnection)
						{
							log.info("Account setup required. Link: {}", link);
							setupLinkLoggedThisConnection = true;
						}
						else
						{
							log.debug("Account setup required (reconnect). Link: {}", link);
						}
					}
					else
					{
						// Account already set up — clear any stale link
						setupLink = null;
						setupLinkExpiry = 0;
					}
					log.debug("WS authenticated for {}", activeUsername);
					// Flush any SESSION_START that arrived before authentication completed
					SplashSession pending = pendingSessionStart;
					if (pending != null)
					{
						pendingSessionStart = null;
						sendSessionStart(pending);
					}
					// Notify the plugin so it can re-send SESSION_START for any ongoing session
					Runnable cb = onAuthSuccessCallback;
					if (cb != null)
					{
						cb.run();
					}
					break;

				case "AUTH_FAILURE":
					String reason = msg.has("reason") ? msg.get("reason").getAsString() : "unknown";
					if ("Not authenticated".equalsIgnoreCase(reason))
					{
						log.debug("WS received pre-auth rejection, retrying AUTH for {}", activeUsername);
						if (connected.get())
						{
							executor().execute(this::sendAuth);
						}
						break;
					}

					log.warn("WS auth failed for {}: {}", activeUsername, reason);
					authenticated.set(false);
					if ("Invalid token".equalsIgnoreCase(reason)
						|| "username and token are required".equalsIgnoreCase(reason)
						|| "Missing message type".equalsIgnoreCase(reason)
						|| "Invalid JSON".equalsIgnoreCase(reason))
					{
						// Fatal auth failures should halt reconnect loops until user action.
						intentionalDisconnect = true;
						if ("Invalid token".equalsIgnoreCase(reason))
						{
							log.warn("Sync token appears to belong to a different account. "
								+ "Use the 'Reset Token' button in the Splash Statistics panel to fix this.");
						}
					}
					break;

				case "ACK":
					log.debug("WS ACK received");
					break;

				default:
					log.debug("Unknown WS message type: {}", type);
					break;
			}
		}
		catch (Exception e)
		{
			log.error("Error handling WS message", e);
		}
	}

	private JsonObject buildSessionData(SplashSession session)
	{
		JsonObject obj = new JsonObject();
		obj.addProperty("playerName", session.getPlayerName());
		obj.addProperty("spell", session.getSpell() != null ? session.getSpell().getName() : "Unknown");
		obj.addProperty("runeCostPerCast", session.getRuneCostPerCast());
		obj.addProperty("startTime", session.getStartTime().toString());
		Instant logoutTime = session.getLogoutTime();
		obj.addProperty("logoutTime", logoutTime != null ? logoutTime.toString() : session.getStartTime().toString());
		obj.addProperty("world", session.getWorld());
		obj.addProperty("stickyKnight", session.isStickyKnight());
		obj.addProperty("spellsCast", session.getSpellsCast());
		obj.addProperty("startMagicXp", session.getStartMagicXp());
		obj.addProperty("currentMagicXp", session.getCurrentMagicXp());
		obj.addProperty("knightMovements", session.getKnightMovements());
		obj.addProperty("highestPlayerCount", session.getHighestPlayerCount());
		obj.addProperty("averagePlayerCount", session.getAveragePlayerCount());
		obj.addProperty("currentPlayerCount", session.getCurrentPlayerCount());
		obj.addProperty("pickpocketerCount", session.getPickpocketerCount());
		obj.addProperty("playerDeaths", session.getPlayerDeaths());
		obj.addProperty("level99Count", session.getLevel99Count());
		obj.addProperty("startingRuneCount", session.getStartingRuneCount());
		obj.addProperty("currentRuneCount", session.getCurrentRuneCount());
		JsonObject runeMap = new JsonObject();
		for (Map.Entry<Integer, Integer> entry : session.getRuneUsageMap().entrySet())
		{
			runeMap.addProperty(entry.getKey().toString(), entry.getValue());
		}
		obj.add("runeUsageMap", runeMap);
		obj.addProperty("runeCostGp", session.getRuneCostGp());

		// Downsampled player-count-over-time series for server-side graphs.
		// Buckets of -1 mean "no data" (e.g. logout gap inside the resume window).
		PlayerCountSeries series = session.getPlayerCountSeries();
		if (series != null)
		{
			JsonObject seriesObj = new JsonObject();
			seriesObj.addProperty("bucketSeconds", series.getBucketSeconds());
			JsonArray buckets = new JsonArray();
			for (Integer bucket : series.getBuckets())
			{
				buckets.add(bucket);
			}
			seriesObj.add("buckets", buckets);
			obj.add("playerCountSeries", seriesObj);
		}
		return obj;
	}

	/**
	 * Extract the 'exp' claim from a setup link URL containing a JWT token query parameter.
	 * Returns epoch seconds, or 0 if unparseable.
	 */
	private long parseJwtExpiry(String link)
	{
		try
		{
			int idx = link.indexOf("token=");
			if (idx < 0) return 0;
			String jwt = link.substring(idx + 6);
			int ampIdx = jwt.indexOf('&');
			if (ampIdx > 0) jwt = jwt.substring(0, ampIdx);

			String[] parts = jwt.split("\\.");
			if (parts.length < 2) return 0;

			String payload = new String(Base64.getUrlDecoder().decode(parts[1]));
			JsonObject obj = gson.fromJson(payload, JsonObject.class);
			if (obj != null && obj.has("exp"))
			{
				return obj.get("exp").getAsLong();
			}
		}
		catch (Exception e)
		{
			log.debug("Could not parse JWT expiry from setup link", e);
		}
		return 0;
	}

	/**
	 * Builds a per-account config key so each OSRS account logged into this RuneLite
	 * profile gets its own token, instead of all accounts sharing (and overwriting)
	 * a single "playerToken" value.
	 */
	private String tokenConfigKey(String username)
	{
		return TOKEN_CONFIG_KEY + "_" + username.trim().toLowerCase().replaceAll("[^a-z0-9]", "_");
	}

	private String getOrCreateToken(String username)
	{
		if (username == null || username.trim().isEmpty())
		{
			return UUID.randomUUID().toString();
		}
		String key = tokenConfigKey(username);
		String token = configManager.getConfiguration(CONFIG_GROUP, key);
		if (token == null || token.trim().isEmpty())
		{
			// Fall back to migrating the old shared token if present, so existing users
			// don't get silently re-linked to a new server-side account on upgrade.
			String legacyToken = configManager.getConfiguration(CONFIG_GROUP, TOKEN_CONFIG_KEY);
			if (legacyToken != null && !legacyToken.trim().isEmpty())
			{
				token = legacyToken;
				configManager.unsetConfiguration(CONFIG_GROUP, TOKEN_CONFIG_KEY);
				log.info("Migrated legacy player token to per-account storage for {}", username);
			}
			else
			{
				token = UUID.randomUUID().toString();
				log.info("Generated new player token for server sync ({})", username);
			}
			configManager.setConfiguration(CONFIG_GROUP, key, token);
		}
		return token;
	}

	// ==================== WebSocket listener ====================

	private class WsListener extends WebSocketListener
	{
		@Override
		public void onOpen(WebSocket ws, Response response)
		{
			// Set webSocket BEFORE sendAuth so it's non-null once auth starts.
			webSocket = ws;
			connected.set(true);
			authenticated.set(false);
			connecting.set(false);
			reconnectScheduled.set(false);
			// Reset the per-connection setup-link log flag so the first AUTH_SUCCESS
			// on this new connection logs at info level.
			setupLinkLoggedThisConnection = false;
			log.debug("WS connected to server, authenticating...");
			sendAuth();
		}

		@Override
		public void onMessage(WebSocket ws, String text)
		{
			handleMessage(text);
		}

		@Override
		public void onClosing(WebSocket ws, int code, String reason)
		{
			ws.close(code, reason);
		}

		@Override
		public void onClosed(WebSocket ws, int code, String reason)
		{
			log.debug("WS closed ({}): {}", code, reason);
			connecting.set(false);
			connected.set(false);
			authenticated.set(false);
			if (!intentionalDisconnect)
			{
				scheduleReconnect();
			}
		}

		@Override
		public void onFailure(WebSocket ws, Throwable t, Response response)
		{
			log.debug("WS error: {}", t.getMessage());
			connecting.set(false);
			connected.set(false);
			authenticated.set(false);
			if (!intentionalDisconnect)
			{
				scheduleReconnect();
			}
		}
	}
}

package xyz.peppie.splashhelper.overlays;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import xyz.peppie.splashhelper.SplashHelperPlugin;
import xyz.peppie.splashhelper.model.TimerAlertLevel;
import xyz.peppie.splashhelper.service.TileManager;

public class SplashHelperOverlay extends Overlay
{
	/** Shared with VisualNotificationOverlay so text and tint change together. */
	public static final Color WARNING_COLOR = new Color(255, 140, 0);
	public static final Color CRITICAL_COLOR = Color.RED;

	private SplashHelperPlugin plugin;
	private TileManager tileManager;
	private final PanelComponent panelComponent = new PanelComponent();

	@Inject
	private SplashHelperOverlay()
	{
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
	}

	public void setPlugin(SplashHelperPlugin plugin, TileManager tileManager)
	{
		this.plugin = plugin;
		this.tileManager = tileManager;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		String overlayTitle = "Splash Timer";

		// Add title
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(overlayTitle)
			.color(Color.CYAN)
			.build());

		panelComponent.setPreferredSize(new Dimension(
            graphics.getFontMetrics().stringWidth(overlayTitle) + 90,
            0));

		// Check if plugin is initialized
		if (plugin == null)
		{
			return null;
		}

		// Show boundary tile status
		if (tileManager.getBoundaryTile() != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Boundary:")
				.right("SET")
				.rightColor(Color.GREEN)
				.build());
		}

		// Show movement tracking stats
		if (tileManager.getKnightTile1() != null && tileManager.getKnightTile2() != null)
		{
			double movementsPerHour = tileManager.getMovementsPerHour();
			String movementText = String.format("%.1f/hr", movementsPerHour);

			Color movementColor = Color.CYAN;
			if (movementsPerHour > 0)
			{
				movementColor = Color.GREEN;
			}

			panelComponent.getChildren().add(LineComponent.builder()
				.left("Movements:")
				.right(movementText)
				.rightColor(movementColor)
				.build());
		}

		// Check if timer is initialized
		if (plugin.getTimerEnd() == null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Timer:")
				.right("Not started")
				.rightColor(Color.GRAY)
				.build());
			return panelComponent.render(graphics);
		}

		// Calculate remaining time
		Duration remaining = Duration.between(Instant.now(), plugin.getTimerEnd());

		if (remaining.isNegative() || remaining.isZero())
		{
			// Timer expired
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Time:")
				.right("EXPIRED")
				.rightColor(Color.RED)
				.build());
		}
		else
		{
			// Format time as MM:SS
			long totalSeconds = remaining.getSeconds();
			long minutes = totalSeconds / 60;
			long seconds = totalSeconds % 60;
			String timeString = String.format("%02d:%02d", minutes, seconds);

			// Same thresholds as the visual notification tint
			TimerAlertLevel level = plugin.getTimerAlertLevel();
			Color timeColor = Color.GREEN;
			if (level == TimerAlertLevel.WARNING)
			{
				timeColor = WARNING_COLOR;
			}
			else if (level == TimerAlertLevel.CRITICAL || level == TimerAlertLevel.EXPIRED)
			{
				timeColor = CRITICAL_COLOR;
			}

			panelComponent.getChildren().add(LineComponent.builder()
				.left("Time Remaining:")
				.right(timeString)
				.rightColor(timeColor)
				.build());
		}

		return panelComponent.render(graphics);
	}
}

package xyz.peppie.splashhelper.overlays;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import xyz.peppie.splashhelper.SplashHelperConfig;
import xyz.peppie.splashhelper.service.TileManager;

public class BoundaryTileOverlay extends Overlay
{
	private final Client client;
	private final SplashHelperConfig config;
	private final TileManager tileManager;

	@Inject
	private BoundaryTileOverlay(Client client, SplashHelperConfig config, TileManager tileManager)
	{
		this.client = client;
		this.config = config;
		this.tileManager = tileManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Stroke originalStroke = graphics.getStroke();

		// Render boundary tile
		if (tileManager.getBoundaryTile() != null)
		{
			renderTile(graphics, tileManager.getBoundaryTile(), config.boundaryTileColor(), originalStroke);
		}

		// Render Knight Tile 1
		if (tileManager.getKnightTile1() != null)
		{
			renderTile(graphics, tileManager.getKnightTile1(), config.knightTile1Color(), originalStroke);
		}

		// Render Knight Tile 2
		if (tileManager.getKnightTile2() != null)
		{
			renderTile(graphics, tileManager.getKnightTile2(), config.knightTile2Color(), originalStroke);
		}

		return null;
	}

	private void renderTile(Graphics2D graphics, WorldPoint worldPoint, java.awt.Color color, Stroke originalStroke)
	{
		// Client is guaranteed to be non-null by dependency injection in RuneLite plugins
		final Client safeClient = client;
		if (safeClient == null) {
			return;
		}

		LocalPoint localPoint = LocalPoint.fromWorld(safeClient.getTopLevelWorldView(), worldPoint);

		if (localPoint == null)
		{
			return;
		}

		// Get the tile polygon
		Polygon tilePoly = Perspective.getCanvasTilePoly(safeClient, localPoint);

		if (tilePoly == null)
		{
			return;
		}

		// Fill with transparent dark gray
		graphics.setColor(new java.awt.Color(0, 0, 0, 100));
		graphics.fillPolygon(tilePoly);

		// Draw colored border
		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(color);
		graphics.drawPolygon(tilePoly);
		graphics.setStroke(originalStroke);
	}
}

package xyz.peppie.splashhelper.overlays;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Stroke;

/**
 * Shared drawing helpers for the guide overlays.
 */
final class GuideOverlayUtil
{
	private GuideOverlayUtil() {}

	/**
	 * Draws a downward-pointing arrow hovering {@code gap}px above the top-centre of {@code bounds},
	 * its tip aimed at the highlight. {@code size} is the arrow's total height in pixels; the width
	 * scales from it — a narrow shaft on top widening into the head — and the border is a thin 1px
	 * outline. Colour matches the highlight it annotates.
	 */
	static void arrowAbove(Graphics2D graphics, Rectangle bounds, Color color, int size, int gap)
	{
		if (bounds == null || size <= 0)
		{
			return;
		}

		int cx = bounds.x + bounds.width / 2;
		int tipY = bounds.y - gap;
		int topY = tipY - size;
		int shoulderY = topY + Math.round(size * 0.45f); // where the shaft meets the head wings

		int headHalf = Math.max(2, Math.round(size * 0.40f));
		int shaftHalf = Math.max(1, Math.round(size * 0.13f)); // narrow at the top

		Polygon arrow = new Polygon();
		arrow.addPoint(cx - shaftHalf, topY);        // shaft top-left
		arrow.addPoint(cx - shaftHalf, shoulderY);   // shaft down to the head, left
		arrow.addPoint(cx - headHalf, shoulderY);    // head wing left
		arrow.addPoint(cx, tipY);                    // tip (points at the highlight)
		arrow.addPoint(cx + headHalf, shoulderY);    // head wing right
		arrow.addPoint(cx + shaftHalf, shoulderY);   // shaft down to the head, right
		arrow.addPoint(cx + shaftHalf, topY);        // shaft top-right

		Stroke prev = graphics.getStroke();
		graphics.setColor(color);
		graphics.fillPolygon(arrow);
		graphics.setStroke(new BasicStroke(1f));
		graphics.setColor(Color.BLACK);
		graphics.drawPolygon(arrow);
		graphics.setStroke(prev);
	}
}

package xyz.peppie.splashhelper.overlays;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import xyz.peppie.splashhelper.SplashHelperConfig;
import xyz.peppie.splashhelper.guide.GuideConstants;
import xyz.peppie.splashhelper.guide.GuideEngine;
import xyz.peppie.splashhelper.guide.GuideStep;

/**
 * Text panel for the guide: the acknowledgement screen before start, then per-step progress,
 * the current instruction, and the armor / stuck warnings.
 */
public class GuidePanelOverlay extends OverlayPanel
{
	private final GuideEngine engine;
	private final SplashHelperConfig config;

	@Inject
	private GuidePanelOverlay(GuideEngine engine, SplashHelperConfig config)
	{
		this.engine = engine;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		switch (engine.getState())
		{
			case AWAITING_ACK:
				return renderAck(graphics);
			case RUNNING:
				return renderRunning(graphics);
			default:
				return null;
		}
	}

	private Dimension renderAck(Graphics2D graphics)
	{
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Sticky Knight Setup")
			.color(Color.CYAN)
			.build());

		addHeader("Main account:");
		for (String req : GuideConstants.MAIN_REQUIREMENTS)
		{
			addBullet(req);
		}
		addHeader("Alt account:");
		for (String req : GuideConstants.ALT_REQUIREMENTS)
		{
			addBullet(req);
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Press [" + config.guideNextHotkey().toString() + "] to acknowledge & begin")
			.leftColor(Color.YELLOW)
			.build());

		panelComponent.setPreferredSize(new Dimension(320, 0));
		return super.render(graphics);
	}

	private Dimension renderRunning(Graphics2D graphics)
	{
		GuideStep step = engine.currentStep();
		if (step == null)
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Step " + step.label + " / " + engine.totalSteps())
			.color(Color.CYAN)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left(step.title)
			.leftColor(Color.WHITE)
			.build());

		GuideStep.StepPhase phase = engine.currentPhase();
		if (phase != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(phase.instruction)
				.leftColor(Color.LIGHT_GRAY)
				.build());
		}

		if (engine.armorViolation())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Take OFF body/legs/boots!")
				.leftColor(Color.RED)
				.build());
		}

		if (engine.timeoutHintActive())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Stuck? Press [" + config.guideBackHotkey().toString() + "] to go back")
				.leftColor(Color.ORANGE)
				.build());
		}

		panelComponent.setPreferredSize(new Dimension(280, 0));
		return super.render(graphics);
	}

	private void addHeader(String text)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(text)
			.leftColor(Color.ORANGE)
			.build());
	}

	private void addBullet(String text)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left("- " + text)
			.leftColor(Color.LIGHT_GRAY)
			.build());
	}
}

package xyz.peppie.splashhelper.overlays;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import xyz.peppie.splashhelper.SplashHelperConfig;
import xyz.peppie.splashhelper.guide.GuideConstants;
import xyz.peppie.splashhelper.guide.GuideEngine;
import xyz.peppie.splashhelper.guide.GuideStep;
import xyz.peppie.splashhelper.guide.StepHighlight;

/**
 * Draws the interface cues for the active guide phase. Tabs, the special-attack orb and the
 * Entangle spell get a simple box; actual items — inventory items, equipment-slot items and the
 * saved splasher gear — are traced with a tinted, semi-transparent silhouette of the item itself.
 */
public class GuideWidgetOverlay extends Overlay
{
	private static final Color BOX = new Color(0, 200, 255, 255);
	private static final Color ITEM_HIGHLIGHT = new Color(0, 200, 255, 255);
	private static final int ITEM_FILL_ALPHA = 80; // semi-transparent fill over the item shape
	private static final int PAD = 2;

	private final Client client;
	private final GuideEngine engine;
	private final SplashHelperConfig config;
	private final ItemManager itemManager;

	// Cache the tinted fill/outline silhouettes per (itemId, colour) so we scan pixels only once.
	private final Map<Long, ItemGlyph> glyphCache = new HashMap<>();

	@Inject
	private GuideWidgetOverlay(Client client, GuideEngine engine, SplashHelperConfig config, ItemManager itemManager)
	{
		this.client = client;
		this.engine = engine;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	@SuppressWarnings("deprecation")
	public Dimension render(Graphics2D graphics)
	{
		GuideStep.StepPhase phase = engine.currentPhase();
		if (phase == null)
		{
			return null;
		}

		for (StepHighlight h : phase.highlights)
		{
			switch (h.type)
			{
				case WIDGET:
					box(graphics, widgetBounds(client.getWidget(h.id)));
					break;
				case EQUIPMENT_SLOT:
					// Only draw a slot that actually holds an item — empty slots need no unequipping.
					if (!engine.equipmentSlotEmpty(h.slotIndex))
					{
						Widget slot = client.getWidget(h.id);
						if (slot != null && !slot.isHidden())
						{
							itemHighlight(graphics, equippedItemId(h.slotIndex, slot), slot.getBounds());
						}
					}
					break;
				case INVENTORY_ITEM:
					itemHighlight(graphics, h.id, inventoryItemBounds(h.id));
					break;
				case SAVED_GEAR:
					for (int itemId : engine.savedGearItemIds())
					{
						itemHighlight(graphics, itemId, inventoryItemBounds(itemId));
					}
					break;
				default:
					break; // scene-layer highlights handled by GuideSceneOverlay
			}
		}
		return null;
	}

	private Rectangle widgetBounds(Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return null;
		}
		return widget.getBounds();
	}

	private Rectangle inventoryItemBounds(int itemId)
	{
		Widget inv = client.getWidget(GuideConstants.WIDGET_INVENTORY);
		if (inv == null || inv.isHidden())
		{
			return null;
		}
		Widget[] children = inv.getDynamicChildren();
		if (children == null)
		{
			return null;
		}
		for (Widget child : children)
		{
			if (child != null && child.getItemId() == itemId)
			{
				return child.getBounds();
			}
		}
		return null;
	}

	/** A simple box + arrow, for non-item interface elements (tabs, spec orb, spell icon). */
	private void box(Graphics2D graphics, Rectangle bounds)
	{
		if (bounds == null)
		{
			return;
		}
		Rectangle padded = new Rectangle(
			bounds.x - PAD, bounds.y - PAD, bounds.width + PAD * 2, bounds.height + PAD * 2);
		graphics.setColor(BOX);
		graphics.drawRect(padded.x, padded.y, padded.width, padded.height);
		widgetArrow(graphics, padded);
	}

	/** Traces the item's own shape: a semi-transparent fill under a crisp outline, plus an arrow. */
	private void itemHighlight(Graphics2D graphics, int itemId, Rectangle bounds)
	{
		if (bounds == null || itemId <= 0)
		{
			return;
		}
		ItemGlyph glyph = glyph(itemId);
		if (glyph != null)
		{
			graphics.drawImage(glyph.fill, bounds.x, bounds.y, null);
			graphics.drawImage(glyph.outline, bounds.x, bounds.y, null);
		}
		else
		{
			// Item sprite not ready yet — fall back to a box so the cue still shows this frame.
			graphics.setColor(ITEM_HIGHLIGHT);
			graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
		}
		widgetArrow(graphics, bounds);
	}

	/** Worn item id for a slot, preferring the equipment container and falling back to the widget. */
	private int equippedItemId(int slotIndex, Widget slot)
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			Item item = worn.getItem(slotIndex);
			if (item != null && item.getId() > 0)
			{
				return item.getId();
			}
		}
		return slot.getItemId();
	}

	private void widgetArrow(Graphics2D graphics, Rectangle bounds)
	{
		// Interface items/spells are small — a smaller arrow that sits close to (into) the element.
		int size = Math.max(5, Math.round(config.guideArrowSize() * 0.75f));
		GuideOverlayUtil.arrowAbove(graphics, bounds, BOX, size, -10);
	}

	private ItemGlyph glyph(int itemId)
	{
		long key = ((long) itemId << 32) | (ITEM_HIGHLIGHT.getRGB() & 0xFFFFFFFFL);
		ItemGlyph cached = glyphCache.get(key);
		if (cached != null)
		{
			return cached;
		}
		BufferedImage src = itemManager.getImage(itemId, 1, false);
		if (src == null || src.getWidth() <= 0 || src.getHeight() <= 0)
		{
			return null;
		}
		ItemGlyph glyph = buildGlyph(src);
		if (glyph != null)
		{
			glyphCache.put(key, glyph);
		}
		return glyph; // null while the async sprite is still blank — retried next frame
	}

	/** Builds the tinted fill and edge outline from an item sprite's alpha channel. */
	private ItemGlyph buildGlyph(BufferedImage src)
	{
		int w = src.getWidth();
		int h = src.getHeight();
		int rgb = ITEM_HIGHLIGHT.getRGB() & 0x00FFFFFF;
		int fillArgb = (ITEM_FILL_ALPHA << 24) | rgb;
		int lineArgb = (0xFF << 24) | rgb;

		BufferedImage fill = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		BufferedImage outline = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		boolean any = false;

		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				if (!opaque(src, x, y))
				{
					continue;
				}
				any = true;
				fill.setRGB(x, y, fillArgb);
				// An edge pixel is opaque but borders a transparent pixel (or the sprite edge).
				if (!opaque(src, x - 1, y) || !opaque(src, x + 1, y)
					|| !opaque(src, x, y - 1) || !opaque(src, x, y + 1))
				{
					outline.setRGB(x, y, lineArgb);
				}
			}
		}
		return any ? new ItemGlyph(fill, outline) : null;
	}

	private static boolean opaque(BufferedImage img, int x, int y)
	{
		if (x < 0 || y < 0 || x >= img.getWidth() || y >= img.getHeight())
		{
			return false;
		}
		return (img.getRGB(x, y) >>> 24) > 40;
	}

	private static final class ItemGlyph
	{
		private final BufferedImage fill;
		private final BufferedImage outline;

		private ItemGlyph(BufferedImage fill, BufferedImage outline)
		{
			this.fill = fill;
			this.outline = outline;
		}
	}
}

package xyz.peppie.splashhelper.overlays;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import xyz.peppie.splashhelper.SplashHelperConfig;
import xyz.peppie.splashhelper.guide.GuideEngine;
import xyz.peppie.splashhelper.guide.GuideStep;
import xyz.peppie.splashhelper.guide.StepHighlight;

/**
 * Draws the in-world cues for the active guide phase: ground tiles (with optional text)
 * and an outline around the tracked knight.
 */
public class GuideSceneOverlay extends Overlay
{
	private static final Color TILE_COLOR = new Color(0, 200, 255, 255);
	private static final Color EMPHASIZE_COLOR = new Color(255, 230, 0, 255);
	private static final Color KNIGHT_COLOR = new Color(255, 90, 90, 255);
	private static final Color OTHER_PLAYER_COLOR = new Color(80, 220, 120, 255);
	private static final Color FILL = new Color(0, 0, 0, 90);

	private final Client client;
	private final GuideEngine engine;
	private final SplashHelperConfig config;

	@Inject
	private GuideSceneOverlay(Client client, GuideEngine engine, SplashHelperConfig config)
	{
		this.client = client;
		this.engine = engine;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GuideStep.StepPhase phase = engine.currentPhase();
		if (phase == null)
		{
			return null;
		}

		Stroke original = graphics.getStroke();
		for (StepHighlight h : phase.highlights)
		{
			switch (h.type)
			{
				case TILE:
					renderTile(graphics, h, original);
					break;
				case KNIGHT:
					renderKnight(graphics);
					break;
				case OTHER_PLAYER:
					renderOtherPlayer(graphics, h);
					break;
				default:
					break; // widget-layer highlights handled by GuideWidgetOverlay
			}
		}
		graphics.setStroke(original);
		return null;
	}

	private void renderTile(Graphics2D graphics, StepHighlight h, Stroke original)
	{
		if (h.tile == null || client.getTopLevelWorldView() == null)
		{
			return;
		}
		LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), h.tile);
		if (lp == null)
		{
			return;
		}
		Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly == null)
		{
			return;
		}

		Color color = h.color != null ? h.color : (h.emphasize ? EMPHASIZE_COLOR : TILE_COLOR);
		graphics.setColor(FILL);
		graphics.fillPolygon(poly);
		graphics.setStroke(new BasicStroke(h.emphasize ? 3 : 2));
		graphics.setColor(color);
		graphics.drawPolygon(poly);

		if (h.label != null)
		{
			Point textLoc = Perspective.getCanvasTextLocation(client, graphics, lp, h.label, 0);
			if (textLoc != null)
			{
				OverlayUtil.renderTextLocation(graphics, textLoc, h.label, color);
			}
		}

		sceneArrow(graphics, poly.getBounds(), color);
	}

	private void renderKnight(Graphics2D graphics)
	{
		NPC knight = engine.getKnight();
		if (knight == null)
		{
			return;
		}
		// Outline the knight's model rather than the tile it stands on, so the cue tracks the NPC.
		Shape model = knight.getConvexHull();
		if (model == null)
		{
			return;
		}
		graphics.setColor(FILL);
		graphics.fill(model);
		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(KNIGHT_COLOR);
		graphics.draw(model);

		sceneArrow(graphics, model.getBounds(), KNIGHT_COLOR);
	}

	private void renderOtherPlayer(Graphics2D graphics, StepHighlight h)
	{
		if (h.tile == null || client.getTopLevelWorldView() == null)
		{
			return;
		}
		Player local = client.getLocalPlayer();
		Player found = null;
		for (Player p : client.getTopLevelWorldView().players())
		{
			if (p != null && p != local && h.tile.equals(p.getWorldLocation()))
			{
				found = p;
				break;
			}
		}
		if (found == null)
		{
			return; // no one on the tile yet; the accompanying tile highlight still marks the spot
		}
		Shape model = found.getConvexHull();
		if (model == null)
		{
			return;
		}
		graphics.setColor(FILL);
		graphics.fill(model);
		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(OTHER_PLAYER_COLOR);
		graphics.draw(model);

		sceneArrow(graphics, model.getBounds(), OTHER_PLAYER_COLOR);

		if (h.label != null)
		{
			Rectangle b = model.getBounds();
			Point textLoc = new Point(b.x + b.width / 2, b.y);
			OverlayUtil.renderTextLocation(graphics, textLoc, h.label, OTHER_PLAYER_COLOR);
		}
	}

	/** In-world arrow, sized from the configured base with a proportional gap above the target. */
	private void sceneArrow(Graphics2D graphics, Rectangle bounds, Color color)
	{
		int size = config.guideArrowSize();
		GuideOverlayUtil.arrowAbove(graphics, bounds, color, size, Math.max(5, size / 5));
	}
}

package xyz.peppie.splashhelper.overlays;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import xyz.peppie.splashhelper.SplashHelperConfig;

/**
 * Overlay to warn players about grief-prone settings.
 * Shows a red warning in the top-left corner if Accept Aid is on or Private Chat is set to All.
 */
public class GriefPreventionOverlay extends Overlay
{
	private static final int ACCEPT_AID_VARP = 427;
	private static final int PRIVATE_CHAT_VARP = 287;

	// Private chat values: 0 = Off, 1 = Friends, 2 = On (All)
	private static final int PRIVATE_CHAT_ON = 2;

	private final Client client;
	private final SplashHelperConfig config;
	private final PanelComponent panelComponent = new PanelComponent();

	@Inject
	public GriefPreventionOverlay(Client client, SplashHelperConfig config)
	{
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		this.client = client;
		this.config = config;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Only show if grief prevention is enabled in config
		if (!config.enableGriefPrevention())
		{
			return null;
		}

		boolean acceptAidOn = client.getVarpValue(ACCEPT_AID_VARP) == 1;
		int privateChatSetting = client.getVarpValue(PRIVATE_CHAT_VARP);
		// Private chat: 0 = Off, 1 = Friends, 2 = On (All)
		boolean privateChatAll = privateChatSetting == PRIVATE_CHAT_ON;

		// Only show overlay if either setting is problematic
		if (!acceptAidOn && !privateChatAll)
		{
			return null;
		}

		panelComponent.getChildren().clear();

		// Title
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Grief Prevention")
			.color(Color.RED)
			.build());

		// Warning messages
		if (acceptAidOn)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("⚠ Accept Aid: ON")
				.leftColor(Color.RED)
				.build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left("  Turn it OFF")
				.leftColor(Color.ORANGE)
				.build());
		}

		if (privateChatAll)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("⚠ Private Chat: All")
				.leftColor(Color.RED)
				.build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left("  Set to Friends/Off")
				.leftColor(Color.ORANGE)
				.build());
		}

		panelComponent.setBackgroundColor(new Color(70, 0, 0, 200));
		panelComponent.setPreferredSize(new Dimension(200, 0));

		return panelComponent.render(graphics);
	}
}

